// Pregunta libre: estos datos se mandan siempre junto con la pregunta (lo que más pregunta cada perfil).
// Así responde bien aunque el modelo no pida herramientas, y la mayoría de las preguntas salen en una sola vuelta.
// Además, según las palabras de la pregunta, se suman los datos que seguro hacen falta (máximo 3 en total).
const ASIST_PALABRAS = [
  // A quién asignar o derivar (parche 87): va primero para que no lo desplacen otros datos cuando la pregunta nombra varias cosas
  [/deriv|a qui[eé]n|(?<!sin )asignar(le|la|lo)?\b|menos (cargad|carga|ocupad|tareas)|m[aá]s (libre|liviano|descargado)|est[aá] libre|disponible/i, 'opciones_derivacion'],
  [/equipo|carga|cargad|qui[eé]n (la |las )?tiene|asignad|sin asignar|soporte|libre|ocupad/i, 'carga_equipos'],
  [/tarea|me (toc[oó]|asignaron)|sin (tomar|responsable)|otras? salas/i, 'tareas_salas'],
  [/parecid|similar|antes\b|anterior|cerrad|antecedent|otra vez|de nuevo|ya (pas|ocurri|tuvimos|vimos)|la [uú]ltima vez/i, 'casos_parecidos'],
  [/horari|hora |\bhoras?\b|cliente|problema|incidente|mes\b|semana|ranking|m[aá]s (alertas|problemas)|histori|resoluci|mttr|tard[aó]/i, 'incidentes'],
  [/pre.?alerta|empeor|viene subiendo|riesgo/i, 'prealertas'],
  [/estado|c[oó]mo est[aá]|panorama|operaci[oó]n|servicio|canal/i, 'estado_clientes'],
  [/umbral|falsa|ajust|banda|configur/i, 'ajustes_sugeridos'],
  [/activ|abiert|en curso|qui[eé]n .*(trabaj|tiene|mira|ve)/i, 'alertas_abiertas'],
  [/\bmis?\b|tomar|pendiente|tengo/i, 'mis_alertas'],
];
// Parámetros que salen de las palabras de la pregunta (por ejemplo "este mes" → 30 días)
const ASIST_ARGS = { incidentes: (q) => /mes\b|30/i.test(q) ? { dias: 30 } : {} };
function asistElegirPalabras(pregunta, disponibles) {
  const out = [];
  for (const [re, n] of ASIST_PALABRAS) if (re.test(pregunta) && !out.includes(n)) out.push(n);
  return out.filter((n) => disponibles.includes(n));
}
function asistElegir(pregunta, perfil, disponibles) {
  const out = (ASIST_BASE[perfil] || []).slice();
  for (const n of asistElegirPalabras(pregunta, disponibles)) if (!out.includes(n)) out.push(n);
  return out.filter((n) => disponibles.includes(n)).slice(0, 3);
}
const ASIST_BASE = { SOPORTE: ['mis_alertas'], ANALISTA: ['alertas_abiertas'], GERENTE: ['estado_clientes'], ADMIN: ['estado_clientes'] };

// ---------- Llamada al modelo ----------
function asistNormalizar(r) {
  // Workers AI devuelve el formato de OpenAI (choices) o el propio ({response, tool_calls})
  let texto = '', llamadas = [];
  if (r && r.choices && r.choices[0]) {
    const m = r.choices[0].message || {};
    texto = m.content || '';
    llamadas = (m.tool_calls || []).map((t) => ({ id: t.id, nombre: t.function && t.function.name, args: t.function && t.function.arguments }));
  } else if (r) {
    texto = typeof r.response === 'string' ? r.response : r.response ? JSON.stringify(r.response) : '';
    llamadas = (r.tool_calls || []).map((t, i) => ({ id: t.id || 'llamada_' + i, nombre: t.name || (t.function && t.function.name), args: t.arguments || (t.function && t.function.arguments) }));
  }
  llamadas = llamadas.filter((x) => x.nombre).map((x) => {
    let a = x.args;
    if (typeof a === 'string') { try { a = JSON.parse(a); } catch (e) { a = {}; } }
    return { id: x.id || 'llamada', nombre: String(x.nombre), args: a && typeof a === 'object' ? a : {} };
  });
  texto = String(texto || '').replace(/<think>[\s\S]*?<\/think>/g, '').replace(/^[\s\S]*<\/think>/, '').trim();
  return { texto, llamadas };
}
// Cambia los códigos [N1] / [E2] que escribe el modelo por enlaces reales (solo los que mandó el servidor)
function asistEnlaces(t, enl) {
  return t
    .replace(/\[([^\[\]]{1,40})\]\(\s*\[?([EN]\d{1,2})\]?\s*\)/g, (m, l, k) => enl[k] ? '[' + l + '](' + enl[k] + ')' : l)
    .replace(/[\[(]([EN]\d{1,2})[\])]/g, (m, k) => enl[k] ? '[más info](' + enl[k] + ')' : '')
    .replace(/\[más info\]\(\s*\)/g, '');
}
// Lo que nunca se le muestra a la persona: definiciones o llamadas de herramientas escritas como texto
const asistEsEco = (t) => /<\/?tools>|<tool_call>|<tool_response>|"type"\s*:\s*"function"/.test(t || '');
function asistLimpiarTexto(t) {
  return String(t || '')
    .replace(/^[ \t]*#{1,6}[ \t]+(.+?)[ \t#]*$/gm, (m, t) => '**' + t.replace(/\*\*/g, '') + '**')   // títulos ### → negrita (el panel no muestra #)
    .replace(/^[ \t]*<\/?[a-z_]{2,40}>[ \t]*$/gim, '')                       // etiquetas sueltas tipo <resumen_turno>
    .replace(/^[ \t]*[-*•]?[ \t]*\**(id|alerta_id)\**:?\**[ \t]*[0-9a-f]{32}[ \t]*$/gim, '') // renglones con el id interno
    .replace(/\s*\(?\b[0-9a-f]{32}\b\)?/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/<tools>[\s\S]*?(<\/tools>|$)/g, '')
    .replace(/<tool_call>[\s\S]*?(<\/tool_call>|$)/g, '')
    .replace(/<tool_response>[\s\S]*?(<\/tool_response>|$)/g, '')
    .trim();
}
// Algunos modelos no aceptan mensajes de herramientas: se reintenta con los resultados como texto
function asistSinMensajesDeHerramienta(mensajes) {
  const out = [];
  let datos = [];
  for (const m of mensajes) {
    if (m.role === 'tool') { datos.push(m.name + ': ' + m.content); continue; }
    if (datos.length) { out.push({ role: 'user', content: 'Resultados de las herramientas (JSON):\n' + datos.join('\n') }); datos = []; }
    if (m.role === 'assistant' && m.tool_calls) { if (m.content) out.push({ role: 'assistant', content: m.content }); continue; }
    out.push(m);
  }
  if (datos.length) out.push({ role: 'user', content: 'Resultados de las herramientas (JSON):\n' + datos.join('\n') + '\nRespondé la pregunta con estos datos.' });
  return out;
}
async function asistModelo(env, mensajes, herramientas, nombres) {
  const modelo = asistNombreModelo(env);
  const pedido = { messages: mensajes, max_tokens: ASIST_TOKENS_RESPUESTA, temperature: 0.2 };
  if (herramientas && herramientas.length) pedido.tools = herramientas;
  // Gemma 4 "piensa" antes de responder y puede gastar todos los tokens en eso (respuesta vacía, 17/11): se le apaga el
  // razonamiento. Si Workers AI no aceptara el parámetro, se repite el mismo pedido sin él.
  const correr = async (p) => {
    if (asistPiensa(modelo)) {
      try { return await env.AI.run(modelo, Object.assign({}, p, { chat_template_kwargs: { enable_thinking: false } })); }
      catch (e) {
        // Solo si el error es por el formato del pedido (el parámetro); otro error (modelo caído) sigue como siempre
        if (!/chat_template|enable_thinking|template|schema|oneOf|additional|invalid input|5006/i.test(e.message || '')) throw e;
        console.error('Asistente: ' + modelo + ' no aceptó enable_thinking = false: ' + e.message);
      }
    }
    return env.AI.run(modelo, p);
  };
  let r;
  try { r = await correr(pedido); }
  catch (e) {
    if (!mensajes.some((m) => m.role === 'tool')) throw e;
    pedido.messages = asistSinMensajesDeHerramienta(mensajes);
    r = await correr(pedido);
  }
  let n = asistNormalizar(r);
  // Respuesta vacía (un modelo que "piensa" puede gastar todos los tokens antes de escribir): se deja el detalle en el registro y se reintenta una vez con más margen
  if (!n.texto && !n.llamadas.length && r) {
    try { console.error('Asistente: respuesta vacía de ' + modelo + ': ' + JSON.stringify(r).slice(0, 700)); } catch (e) { /* sin detalle */ }
    try { n = asistNormalizar(await correr(Object.assign({}, pedido, { max_tokens: ASIST_TOKENS_RESPUESTA * 3 }))); } catch (e) { /* queda vacía */ }
  }
  // Formato Hermes/Qwen: la llamada viene como texto entre <tool_call> … </tool_call>
  if (!n.llamadas.length && nombres && /<tool_call>/.test(n.texto)) {
    const lista = [];
    for (const m of n.texto.matchAll(/<tool_call>\s*([\s\S]*?)\s*(<\/tool_call>|$)/g)) {
      try {
        const x = JSON.parse(m[1]);
        const nom = x.name || (x.function && x.function.name);
        if (nombres.includes(nom)) lista.push({ id: 'texto_' + lista.length, nombre: nom, args: (typeof x.arguments === 'string' ? JSON.parse(x.arguments) : x.arguments || x.parameters) || {} });
      } catch (e) { /* llamada mal escrita: se ignora */ }
    }
    if (lista.length) return { texto: asistLimpiarTexto(n.texto), llamadas: lista };
  }
  // Llamada escrita como texto: sugerir_accion(tipo="escalar", …) (parche 72)
  if (!n.llamadas.length && nombres) { const x = asistLlamadasEnTexto(n.texto, nombres); if (x.lista.length) return { texto: x.texto, llamadas: x.lista }; }
  // Hay modelos que devuelven la llamada como texto JSON en vez de usar tool_calls
  if (!n.llamadas.length && nombres && /^\s*[\[{]/.test(n.texto)) {
    try {
      const j = JSON.parse(n.texto.replace(/^```(json)?|```$/g, ''));
      const lista = (Array.isArray(j) ? j : [j]).filter((x) => x && nombres.includes(x.name || (x.function && x.function.name)));
      if (lista.length) return { texto: '', llamadas: lista.map((x, i) => ({ id: 'texto_' + i, nombre: x.name || x.function.name, args: (typeof x.arguments === 'string' ? JSON.parse(x.arguments) : x.arguments || x.parameters) || {} })) };
    } catch (e) { /* era texto común */ }
  }
  return n;
}

// ---------- Llamadas escritas como texto: nombre(clave="valor", …) (parche 72) ----------
const ASIST_ARG_TEXTO = /(\w+)\s*=\s*(?:"((?:[^"\\]|\\.)*)"|'((?:[^'\\]|\\.)*)'|(-?\d+(?:\.\d+)?)|(true|false|null))/g;
function asistLlamadasEnTexto(texto, nombres) {
  const lista = [];
  if (!texto || !nombres || !nombres.length) return { texto, lista };
  const re = new RegExp('`*\\b(' + nombres.map((n) => n.replace(/\W/g, '')).join('|') + ')\\(((?:"(?:[^"\\\\]|\\\\.)*"|\'(?:[^\'\\\\]|\\\\.)*\'|[^()"\'])*)\\)`*', 'g');
  const limpio = texto.replace(re, (m, nom, cuerpo) => {
    if (cuerpo.trim() && !/=/.test(cuerpo)) return m;   // texto común con paréntesis: no es una llamada
    const args = {};
    for (const a of cuerpo.matchAll(ASIST_ARG_TEXTO)) args[a[1]] = a[2] != null ? a[2] : a[3] != null ? a[3] : a[4] != null ? Number(a[4]) : a[5] === 'true' ? true : a[5] === 'false' ? false : null;
    lista.push({ id: 'texto_' + lista.length, nombre: nom, args });
    return '';
  });
  return { texto: limpio.replace(/\n{3,}/g, '\n\n').trim(), lista };
}
const asistBorrarLlamadasEnTexto = (t) => asistLlamadasEnTexto(t, Object.keys(ASIST_HERRAMIENTAS).concat(['sugerir_accion'])).texto;

// Una pregunta completa: datos permitidos + hasta 3 vueltas con el modelo. Devuelve texto y acciones propuestas.
async function asistResponder(env, yo, entrada) {
  const ahora = await asistAhora(env);
  const enSala = !!entrada.incidente_id;
  const disponibles = asistDisponibles(yo).filter((n) => enSala || !ASIST_HERRAMIENTAS[n].soloSala);
  const schemas = asistSchemas(disponibles, yo, enSala);
  const acciones = [], usadas = [], enlaces = {};
  let consultas = 0, motivoEscalar = null;
  const correrHerramienta = async (nombre, args) => {
    if (nombre === 'sugerir_accion') {
      if (acciones.length >= ASIST_MAX_ACCIONES) return { error: 'Ya hay suficientes acciones propuestas.' };
      const p = await asistValidarAccion(env, yo, args || {});
      if (p.error) { if (args && args.tipo === 'escalar' && (args.motivo || args.comentario)) motivoEscalar = String(args.comentario || args.motivo).slice(0, 600); return p; }
      if (!acciones.some((x) => x.tipo === p.tipo && (x.clave || x.alerta_id) === (p.clave || p.alerta_id))) acciones.push(p);
      return { ok: true, nota: 'Propuesta lista. La persona la ve con un botón "Hacerlo" y decide. No digas que se hizo.' };
    }
    if (!disponibles.includes(nombre)) return { error: 'La herramienta ' + nombre + ' no está disponible para el perfil ' + ASIST_PERFIL_TXT[yo.perfil] + '.' };
    if (consultas >= ASIST_MAX_HERRAMIENTAS) return { error: 'Límite de consultas por pregunta alcanzado: respondé con lo que ya tenés.' };
    consultas++; usadas.push(nombre);
    try {
      const res = await ASIST_HERRAMIENTAS[nombre].ejecutar(env, yo, args || {});
      // Enlaces largos: el modelo solo ve un código ([N1]) y acá se guarda el enlace real para ponerlo al final
      if (res && res._enlaces) { Object.assign(enlaces, res._enlaces); delete res._enlaces; }
      return res;
    }
    catch (e) { console.error('Asistente, ' + nombre + ': ' + e.message); return { error: 'No se pudo leer ese dato.' }; }
  };

  const mensajes = [{ role: 'system', content: asistSistema(yo, ahora, disponibles) + (entrada.incidente_id ? '\n' + ASIST_REGLA_SALA.replace('{ID}', entrada.incidente_id) : '') }];
  for (const h of entrada.historia) mensajes.push(h);
  let pregunta = entrada.pregunta;
  // Pregunta sugerida o "¿Qué está pasando?" de una alerta: los datos se traen directo (una sola llamada al modelo)
  const directas = [];
  let datosDirectos = null;
  // Pregunta libre dentro de la conversación de una alerta: los datos de esa alerta llegan siempre (y, según las palabras, hasta 3 datos más)
  const alertaCtx = entrada.alerta_contexto && !entrada.alerta_id && !entrada.sugerencia && !entrada.incidente_id ? entrada.alerta_contexto : null;
  if (alertaCtx) {
    directas.push(['detalle_alerta', { alerta_id: alertaCtx }]);
    for (const n of asistElegirPalabras(entrada.pregunta, disponibles).filter((x) => x !== 'detalle_alerta').slice(0, 3)) directas.push([n, ASIST_ARGS[n] ? ASIST_ARGS[n](entrada.pregunta) : {}]);
  }
  if (entrada.alerta_id) directas.push(['detalle_alerta', { alerta_id: entrada.alerta_id }]);
  const salaLibre = !!(entrada.incidente_id && !entrada.sugerencia);
  if (salaLibre) for (const n of salaElegir(entrada.pregunta, disponibles))   // pregunta libre dentro de la sala (parche 71)
    directas.push([n, n === 'contexto_externo' ? ASIST_ARGS.contexto_externo(entrada.pregunta) : { incidente_id: entrada.incidente_id }]);
  if (entrada.sugerencia) for (const n of entrada.sugerencia.herramientas) directas.push([n, (entrada.sugerencia.args || {})[n] || {}]);
  if (!directas.length) for (const n of asistElegir(entrada.pregunta, yo.perfil, disponibles)) directas.push([n, ASIST_ARGS[n] ? ASIST_ARGS[n](entrada.pregunta) : {}]);
  if (directas.length) {
    const datos = {};
    for (const [n, a] of directas) datos[n] = await correrHerramienta(n, a);
    datosDirectos = datos;
    // Propuesta armada por el servidor (por ejemplo, "Tomar" la primera de Soporte): no depende de que el modelo la pida
    if (entrada.sugerencia && entrada.sugerencia.proponer) { const p = entrada.sugerencia.proponer(datos); for (const x of (Array.isArray(p) ? p : p ? [p] : [])) await correrHerramienta('sugerir_accion', x); }
    pregunta += '\n\nDatos de Helios para responder (JSON):\n' + JSON.stringify(datos);
    if (alertaCtx) pregunta += '\n\nLa persona está mirando una alerta concreta (la de detalle_alerta) y su pregunta se refiere a ella, salvo que nombre otra. No le pidas que aclare de qué alerta habla.';
    if (salaLibre) pregunta += '\n\nCómo responder: ' + SALA_GUIA_LIBRE;
    if (entrada.sugerencia && entrada.sugerencia.guia) pregunta += '\n\nCómo responder: ' + entrada.sugerencia.guia + (acciones.length ? ' (Ya le dejamos a la persona el botón "Hacerlo" para: ' + acciones.map((x) => x.titulo.toLowerCase()).join(', ') + '.)' : '');
  }
  if (/qwen3/i.test(asistNombreModelo(env))) pregunta += ' /no_think';
  mensajes.push({ role: 'user', content: pregunta });

  let texto = '', crudo = '', insistio = false;
  for (let vuelta = 0; vuelta < ASIST_MAX_VUELTAS; vuelta++) {
    const ultima = vuelta === ASIST_MAX_VUELTAS - 1;
    let r = await asistModelo(env, mensajes, ultima ? null : schemas, ultima ? null : schemas.map((x) => x.function.name));
    crudo = (r.texto || '') + (r.llamadas.length ? ' [llamadas: ' + r.llamadas.map((l) => l.nombre).join(',') + ']' : '');
    if (!r.llamadas.length && asistEsEco(r.texto)) {
      // Repitió la definición de las herramientas en vez de usarlas: se pide la respuesta con los datos que ya hay
      r = await asistModelo(env, mensajes.concat([{ role: 'user', content: 'Respondé la pregunta en español, con los datos que ya tenés. No escribas herramientas ni JSON.' }]), null, null);
      texto = r.texto; break;
    }
    if (!r.llamadas.length && !ultima && !insistio && ASIST_PROMESA.test(r.texto || '')) {
      insistio = true;
      mensajes.push({ role: 'assistant', content: r.texto }, { role: 'user', content: 'No anuncies consultas: si te falta un dato, pedí la herramienta ahora; si no, respondé ya con lo que tenés.' });
      continue;
    }
    if (!r.llamadas.length || ultima) { texto = r.texto; break; }
    mensajes.push({ role: 'assistant', content: r.texto || '', tool_calls: r.llamadas.map((l) => ({ id: l.id, type: 'function', function: { name: l.nombre, arguments: JSON.stringify(l.args) } })) });
    let soloAcciones = true;
    for (const l of r.llamadas.slice(0, 4)) {
      if (l.nombre !== 'sugerir_accion') soloAcciones = false;
      const res = await correrHerramienta(l.nombre, l.args);
      mensajes.push({ role: 'tool', tool_call_id: l.id, name: l.nombre, content: JSON.stringify(res).slice(0, 12000) });
    }
    // Si solo propuso acciones y ya había escrito la respuesta, no hace falta otra vuelta
    if (soloAcciones && r.texto) { texto = r.texto; break; }
  }
  if (salaLibre && /escal/i.test(entrada.pregunta) && !acciones.some((a) => a.tipo === 'escalar') && !/no (hace falta|conviene|es necesario|corresponde|har[ií]a falta) escalar/i.test(texto || '')) {
    const p = salaProponerEscalar(datosDirectos, entrada.incidente_id, motivoEscalar);
    const antes = acciones.length;
    if (p) await correrHerramienta('sugerir_accion', p);
    if (acciones.length > antes && texto) texto += '\n\nTe dejo el botón para escalar: queda como tarea para quien lo gestiona (revisá a quién y el texto antes de confirmarlo).';
  }
  texto = asistLimpiarTexto(asistBorrarLlamadasEnTexto(texto));
  if (Object.keys(enlaces).length) texto = asistEnlaces(texto, enlaces);
  if (asistEsEco(texto)) texto = '';
  if (!texto) { try { console.error('Asistente: sin texto final con ' + asistNombreModelo(env) + '; última salida del modelo: ' + JSON.stringify(crudo).slice(0, 600)); } catch (e) { /* sin detalle */ } }
  if (!texto && datosDirectos && entrada.sugerencia && entrada.sugerencia.respaldo) texto = entrada.sugerencia.respaldo(datosDirectos, acciones);
  if (!texto) texto = acciones.length ? 'Te dejo una propuesta para que la revises.' : 'No pude armar una respuesta. Probá preguntarlo de otra forma.';
  if (!acciones.length) texto = asistSinBotonFalso(texto) || 'No pude armar una respuesta. Probá preguntarlo de otra forma.';
  return { respuesta: texto.slice(0, 4000), acciones, herramientas: usadas };
}

// ---------- Saludos y agradecimientos sueltos (parche 74): se contestan sin llamar al modelo ----------
// Un "hola", un "gracias" o un "de nada" no es una pregunta de la operación: no gasta neuronas ni cuenta en el límite de preguntas,
// y no deja registro. Solo cuenta si TODAS las palabras son de cortesía; con cualquier palabra de trabajo ("hola, ¿cómo está CLI_004?") va al modelo.
const ASIST_CORTESIA = {
  gracias: ['gracias', 'agradezco', 'agradecido', 'agradecida', 'muchas', 'mil', 'muchisimas', 'muchisimo', 'mucho', 'ayuda', 'respuesta', 'info', 'informacion', 'util', 'amable', 'rapido', 'excelente', 'genial', 'barbaro', 'perfecto', 'joya', 'de', 'nada', 'por', 'la', 'el', 'lo', 'todo', 'favor', 'muy', 'te', 'ya', 'entendi', 'entendido', 'listo'],
  chau: ['chau', 'chao', 'adios', 'hasta', 'luego', 'pronto', 'manana', 'nos', 'vemos', 'saludos', 'buen', 'buena', 'buenas', 'dia', 'dias', 'tarde', 'tardes', 'noche', 'noches', 'turno', 'descanso', 'que', 'tengas', 'tenga', 'un', 'una'],
  saludo: ['hola', 'holi', 'holis', 'buenas', 'buen', 'buena', 'bueno', 'buenos', 'dia', 'dias', 'tarde', 'tardes', 'noche', 'noches', 'que', 'tal', 'como', 'estas', 'andas', 'va', 'todo', 'bien', 'hey', 'ey', 'helios', 'asistente', 'saludos'],
  asentir: ['ok', 'okey', 'okay', 'oka', 'dale', 'listo', 'perfecto', 'genial', 'excelente', 'barbaro', 'joya', 'entendido', 'claro', 'bien', 'bueno', 'vale', 'jaja', 'jeje', 'jajaja', 'buenisimo', 'de', 'acuerdo', 'ya', 'esta'],
};
const ASIST_CORTESIA_TODAS = new Set([].concat(...Object.values(ASIST_CORTESIA)));
const ASIST_RESP_CORTESIA = {
  gracias: 'De nada. Si necesitás algo más de la operación, preguntame.',
  chau: 'Hasta luego.',
  saludo: 'Hola. Preguntame por la operación de Helios: lo que está abierto, lo pendiente o qué pasa con una alerta.',
  asentir: 'Perfecto. Cuando necesites algo de la operación, preguntame.',
  vacia: 'Escribí una pregunta sobre la operación de Helios: alertas, pre-alertas, clientes o carga de los equipos.',
};
function asistCortesia(texto) {
  const t = String(texto || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z\s]/g, ' ').replace(/(.)\1{2,}/g, '$1');
  if (t.length > 80) return null;
  const palabras = t.split(/\s+/).filter(Boolean);
  if (!palabras.length) return ASIST_RESP_CORTESIA.vacia;               // solo signos, números o emojis
  if (palabras.length > 8 || !palabras.every((p) => ASIST_CORTESIA_TODAS.has(p))) return null;
  // "¿Todo bien?" puede ser una pregunta por el estado de la operación: va al modelo (salvo "gracias por todo")
  if (palabras.includes('todo') && !palabras.some((p) => ['gracias', 'agradezco', 'agradecido', 'agradecida', 'muchisimas', 'muchisimo'].includes(p))) return null;
  for (const tipo of ['gracias', 'chau', 'saludo']) {
    const claves = tipo === 'gracias' ? ['gracias', 'agradezco', 'agradecido', 'agradecida', 'muchisimas', 'muchisimo', 'nada'] : tipo === 'chau' ? ['chau', 'chao', 'adios', 'hasta', 'vemos', 'tengas', 'tenga'] : ['hola', 'holi', 'holis', 'hey', 'ey', 'buenas', 'buenos', 'buen', 'buena', 'dia', 'dias', 'tarde', 'tardes', 'noche', 'noches', 'tal', 'estas', 'andas', 'va', 'todo', 'saludos', 'helios', 'asistente'];
    if (palabras.some((p) => claves.includes(p))) return ASIST_RESP_CORTESIA[tipo];
  }
  return ASIST_RESP_CORTESIA.asentir;
}

// ---------- Rutas ----------
function asistHistoria(h) {
  if (!Array.isArray(h)) return [];
  return h.slice(-ASIST_MAX_HISTORIA).filter((m) => m && (m.rol === 'usuario' || m.rol === 'asistente') && typeof m.texto === 'string')
    .map((m) => ({ role: m.rol === 'usuario' ? 'user' : 'assistant', content: m.texto.slice(0, 1500) }));
}
// ---------- Asistente dentro de la sala de crisis (parche 69) ----------
// Herramientas de solo lectura (permiso sala_crisis y, además, la misma regla de la sala: Soporte solo donde tiene tareas):
//   estado_incidente · tareas_incidente · guia_diagnostico
// Propuestas (nunca ejecuta): asignar_tarea, escalar y comunicar, solo para quien dirige la sala (sala_crisis_dirigir).
// La página de la sala manda incidente_id con cada pregunta y muestra sus propias preguntas sugeridas.
const salaIdArg = { incidente_id: { type: 'integer', description: 'Número del incidente (el de IM-N)' } };
async function salaRolAsist(env, yo, args) {
  const id = aId(args && args.incidente_id);
  if (!id) return { error: { error: 'Falta el número del incidente.' } };
  const rol = await rolEnIncidente(env, yo, id);
  if (rol.error) return { error: { error: 'Esa sala de crisis no está disponible para tu perfil.' } };
  return rol;
}
const salaAhoraMs = async (env) => Date.parse((await env.DB.prepare('SELECT ' + AHORA_SIM + ' AS a').first()).a);
const salaHace = (ahora, iso) => iso ? asistMinutos(Math.max(0, Math.round((ahora - Date.parse(iso)) / 60000))) : null;

Object.assign(ASIST_HERRAMIENTAS, {
  estado_incidente: {
    permiso: 'sala_crisis', soloSala: true,   // se le ofrece al modelo solo si la pregunta se hace dentro de una sala
    descripcion: 'Estado de una sala de crisis: qué pasa, desde cuándo, quién la dirige, qué alertas agrupa y los últimos hechos de su línea de tiempo.',
    parametros: salaIdArg, requeridos: ['incidente_id'],
    async ejecutar(env, yo, args) {
      const rol = await salaRolAsist(env, yo, args); if (rol.error) return rol.error;
      const inc = rol.inc, ahora = await salaAhoraMs(env);
      const r = await env.DB.batch([
        env.DB.prepare(`SELECT ia.tipo_alerta, ia.cliente_id, ia.servicio_id, ia.canal_id, h.estado, h.severidad_maxima FROM incidente_alertas ia
          LEFT JOIN alertas_historico h ON h.alerta_id = ia.alerta_id WHERE ia.incidente_id = ?1 ORDER BY ia.sumada LIMIT ${IM_MAX_ALERTAS}`).bind(inc.id),
        env.DB.prepare(`SELECT l.fecha, l.tipo, l.texto, u.nombre FROM incidente_linea_tiempo l LEFT JOIN usuarios u ON u.id = l.usuario_id
          WHERE l.incidente_id = ?1 ORDER BY l.fecha DESC, l.id DESC LIMIT 8`).bind(inc.id),
        env.DB.prepare('SELECT nombre FROM usuarios WHERE id = ?1').bind(inc.responsable_usuario_id || 0),
        env.DB.prepare(`SELECT estado, COUNT(*) AS n FROM incidente_tareas WHERE incidente_id = ?1 GROUP BY estado`).bind(inc.id),
      ]);
      const t = {}; for (const x of r[3].results) t[x.estado] = x.n;
      return {
        sala: imCodigo(inc.id) + ' · ' + inc.titulo,
        estado: IM_ESTADO_TXT[inc.estado] + (inc.estado === 'CERRADO' && inc.causa_raiz ? ' (causa raíz: ' + inc.causa_raiz + ')' : ''),
        gravedad: ASIST_SEV[inc.severidad] || inc.severidad,
        afecta: [inc.cliente_id || 'varios clientes', inc.servicio_id ? ASIST_SERVICIO[inc.servicio_id] || inc.servicio_id : null].filter(Boolean).join(', '),
        problema_desde: asistFecha(inc.inicio) + ' (hace ' + salaHace(ahora, inc.inicio) + ')',
        sala_abierta_a_las: asistHora(inc.abierto), mitigado_a_las: inc.mitigado ? asistHora(inc.mitigado) : undefined,
        dirige: (r[2].results[0] || {}).nombre || 'sin responsable',
        alertas: r[0].results.map((a) => (ASIST_FRASE[a.tipo_alerta] || a.tipo_alerta) + ' en ' + asistDonde(a) + ' (' + (ASIST_SEV[a.severidad_maxima] || '') +
          ', ' + (a.estado === 'RESUELTA' ? 'ya resuelta' : 'sigue abierta') + ')'),
        tareas: (t.PENDIENTE || 0) + ' pendientes, ' + (t.EN_CURSO || 0) + ' en curso, ' + (t.HECHA || 0) + ' hechas',
        ultimos_hechos: r[1].results.map((l) => asistHora(l.fecha) + ' ' + (l.nombre ? l.nombre + ': ' : '') + l.texto),
      };
    },
  },
  tareas_incidente: {
    permiso: 'sala_crisis', soloSala: true,   // se le ofrece al modelo solo si la pregunta se hace dentro de una sala
    descripcion: 'Tareas de una sala de crisis: quién hace qué, en qué estado, cuánto llevan, cuáles están demoradas y qué encontraron las que ya se hicieron.',
    parametros: salaIdArg, requeridos: ['incidente_id'],
    async ejecutar(env, yo, args) {
      const rol = await salaRolAsist(env, yo, args); if (rol.error) return rol.error;
      const inc = rol.inc, ahora = await salaAhoraMs(env);
      const r = await env.DB.batch([
        env.DB.prepare(`SELECT t.id, t.titulo, t.estado, t.resultado, t.creada, t.actualizada, t.vence, t.componente_id, u.nombre AS persona, e.nombre AS equipo
          FROM incidente_tareas t LEFT JOIN usuarios u ON u.id = t.responsable_usuario_id LEFT JOIN equipos e ON e.id = t.equipo_id
          WHERE t.incidente_id = ?1 ORDER BY t.id LIMIT ${IM_MAX_TAREAS}`).bind(inc.id),
        rol.dirige ? env.DB.prepare(`SELECT u.id, u.nombre, (SELECT COUNT(*) FROM incidente_tareas t WHERE t.responsable_usuario_id = u.id AND t.estado IN ('PENDIENTE', 'EN_CURSO')) AS tareas_abiertas
          FROM usuarios u WHERE u.activo = 1 AND u.perfil = 'SOPORTE' ORDER BY tareas_abiertas, u.nombre LIMIT 20`) : env.DB.prepare('SELECT 1 AS x LIMIT 0'),
        rol.dirige ? env.DB.prepare('SELECT id, nombre FROM equipos WHERE activo = 1 ORDER BY nombre LIMIT 20') : env.DB.prepare('SELECT 1 AS x LIMIT 0'),
      ]);
      // Demorada: pendiente hace más de 20 min, en curso hace más de 60 min, o pasada su hora límite
      const quien = (t) => [t.persona, t.equipo ? 'equipo ' + t.equipo : null].filter(Boolean).join(' · ') || 'sin responsable';
      const frase = (t) => '«' + t.titulo + '» → ' + quien(t) + ' (' + TAREA_ESTADO_TXT[t.estado].toLowerCase() + (t.estado === 'PENDIENTE' || t.estado === 'EN_CURSO' ? ' hace ' + salaHace(ahora, t.actualizada) : '') + ')';
      const demorada = (t) => (t.estado === 'PENDIENTE' && ahora - Date.parse(t.actualizada) > 20 * 60000) || (t.estado === 'EN_CURSO' && ahora - Date.parse(t.actualizada) > 60 * 60000)
        || ((t.estado === 'PENDIENTE' || t.estado === 'EN_CURSO') && t.vence && Date.parse(t.vence) < ahora);
      const ts = r[0].results;
      const abiertas = ts.filter((t) => t.estado === 'PENDIENTE' || t.estado === 'EN_CURSO');
      const out = {
        cuantas: { pendientes: ts.filter((t) => t.estado === 'PENDIENTE').length, en_curso: ts.filter((t) => t.estado === 'EN_CURSO').length,
          hechas: ts.filter((t) => t.estado === 'HECHA').length, demoradas: abiertas.filter(demorada).length },
        abiertas: abiertas.map((t) => frase(t) + (demorada(t) ? ' — DEMORADA' : '')),
        hechas: ts.filter((t) => t.estado === 'HECHA').map((t) => frase(t) + (t.resultado ? ': ' + t.resultado : '')),
        componentes_ya_revisados_o_en_revision: ts.filter((t) => t.estado !== 'CANCELADA').map((t) => t.componente_id).filter(Boolean),
      };
      if (rol.dirige) out.opciones_asignacion = { personas_soporte: r[1].results.map((p) => ({ usuario_id: p.id, nombre: p.nombre, tareas_abiertas: p.tareas_abiertas })),
        equipos: r[2].results.map((e) => ({ equipo_id: e.id, nombre: e.nombre })) };
      return out;
    },
  },
  // Parche 79: las tareas abiertas de TODAS las salas abiertas (no solo la sala de la pregunta), con lo que ve cada perfil: Soporte, las suyas y las de sus equipos;
  // Analista, Gerente y Administrador, todas. «Sin tomar» = asignada a un equipo y todavía sin una persona responsable.
  tareas_salas: {
    permiso: 'sala_crisis',
    descripcion: 'Tareas abiertas (pendientes o en curso) de las salas de crisis abiertas: de quién es cada una, en qué sala, cuánto lleva y cuáles están sin tomar (asignadas a un equipo y sin persona responsable). Soporte ve solo las suyas y las de sus equipos; los demás perfiles ven todas. Para "¿qué tareas tengo?", "¿qué tareas hay sin tomar o sin asignar?".',
    parametros: {},
    async ejecutar(env, yo) {
      const todos = puede(yo, 'sala_crisis_dirigir') || yo.perfil === 'GERENTE' || yo.perfil === 'ADMIN';
      const eq = await misEquipos(env, yo.id);
      const ahora = await salaAhoraMs(env);
      let filas;
      try {
        filas = (await env.DB.prepare(`SELECT t.incidente_id, i.titulo AS sala, t.titulo, t.estado, t.actualizada, t.vence, t.responsable_usuario_id, t.equipo_id, u.nombre AS persona, e.nombre AS equipo
            FROM incidente_tareas t JOIN incidentes_mayores i ON i.id = t.incidente_id AND i.estado <> 'CERRADO'
            LEFT JOIN usuarios u ON u.id = t.responsable_usuario_id LEFT JOIN equipos e ON e.id = t.equipo_id
            WHERE t.estado IN ('PENDIENTE', 'EN_CURSO')
              AND (?2 = 1 OR t.responsable_usuario_id = ?1 OR (t.responsable_usuario_id IS NULL AND t.equipo_id IN (SELECT value FROM json_each(?3))))
            ORDER BY t.incidente_id, CASE t.estado WHEN 'EN_CURSO' THEN 0 ELSE 1 END, t.id LIMIT 40`)
          .bind(yo.id, todos ? 1 : 0, JSON.stringify(eq.miembro.concat(eq.lidero))).all()).results;
      } catch (e) {
        if (/no such table/i.test(e.message)) return { tareas: [], nota: 'Todavía no hay salas de crisis cargadas.' };
        throw e;
      }
      const demorada = (t) => (t.estado === 'PENDIENTE' && ahora - Date.parse(t.actualizada) > 20 * 60000) || (t.estado === 'EN_CURSO' && ahora - Date.parse(t.actualizada) > 60 * 60000)
        || (t.vence && Date.parse(t.vence) < ahora);
      const sinTomar = (t) => t.responsable_usuario_id == null;
      const mia = (t) => t.responsable_usuario_id === yo.id;
      if (!filas.length) return { cuantas: { abiertas: 0 }, nota: todos ? 'No hay tareas abiertas en las salas de crisis.' : 'No hay tareas abiertas asignadas a esta persona ni a sus equipos.' };
      return {
        cuantas: { abiertas: filas.length, asignadas_a_esta_persona: filas.filter(mia).length, sin_tomar: filas.filter(sinTomar).length, demoradas: filas.filter(demorada).length },
        tareas: filas.map((t) => ({ sala: imCodigo(t.incidente_id) + ' · ' + t.sala, tarea: t.titulo, estado: TAREA_ESTADO_TXT[t.estado].toLowerCase() + ' hace ' + salaHace(ahora, t.actualizada),
          de: sinTomar(t) ? 'equipo ' + (t.equipo || '?') + ', todavía sin persona responsable' : t.persona + (t.equipo ? ' (equipo ' + t.equipo + ')' : ''),
          es_de_esta_persona: mia(t) ? true : undefined, demorada: demorada(t) ? true : undefined })),
      };
    },
  },
  guia_diagnostico: {
    permiso: 'sala_crisis', soloSala: true,   // se le ofrece al modelo solo si la pregunta se hace dentro de una sala
    descripcion: 'Guía de diagnóstico de una sala de crisis: de qué componentes depende el servicio afectado, qué revisar en cada uno, quién lo atiende, y los incidentes parecidos ya cerrados con su causa raíz.',
    parametros: salaIdArg, requeridos: ['incidente_id'],
    async ejecutar(env, yo, args) {
      const rol = await salaRolAsist(env, yo, args); if (rol.error) return rol.error;
      const g = await guiaDiagnostico(env, rol.inc);
      return {
        componentes: g.componentes.map((c) => ({ componente_id: c.id, componente: c.nombre, lo_atiende: c.area || undefined, que_revisar: c.que_revisar || undefined,
          depende_de: c.depende_de.length ? c.depende_de.map((d) => d.nombre + (d.que_revisar ? ' (revisar: ' + d.que_revisar + ')' : '')) : undefined })),
        antecedentes: g.antecedentes.map((a) => imCodigo(a.id) + ' (' + asistFecha(a.inicio).slice(0, 5) + ', ' + a.cliente_id + '): ' + a.titulo + '. Causa raíz: ' + (a.causa_raiz || 'sin cargar') +
          (a.componente ? ' (componente: ' + a.componente + ')' : '') + (a.resumen_cierre ? '. ' + a.resumen_cierre : '')),
        causas_frecuentes_de_alertas: g.causas_alertas.length ? g.causas_alertas.map((c) => c.causa + ' (' + c.veces + (c.veces === 1 ? ' vez' : ' veces') + ' en 30 días)') : undefined,
        sin_catalogo: g.componentes.length ? undefined : 'No hay componentes cargados para este servicio: la guía depende del catálogo de infraestructura.',
      };
    },
  },
});

// ---------- Pregunta libre dentro de la sala (parche 71) ----------
const SALA_PALABRAS_GUIA = /escal|proveedor|revis|causa|componente|depend|antecedente|parecid|similar|cerrad|anterior|antes\b|otra vez|de nuevo|la [uú]ltima vez|diagn|por d[oó]nde|empiez|qu[eé] hago|qu[eé] miro|tercer/i;
const SALA_PALABRAS_TAREAS = /tarea.*(tengo|mis?\b|sin (tomar|asignar|responsable)|otras? salas)|(tengo|mis|sin (tomar|asignar|responsable)).*tarea|me (toc[oó]|asignaron)|otras? salas|todas las salas/i;
const SALA_PALABRAS_MIS = /\bmis (alertas|problemas)|alertas? (asignadas?|abiertas?|pendientes?|sin asignar)|sin asignar|tengo (asignad|pendiente)|me (toc[oó]|asignaron)/i;
const SALA_PALABRAS_PARECIDAS = /parecid|similar|antes\b|anterior|cerrad|antecedente|otra vez|de nuevo|la [uú]ltima vez/i;
const SALA_PALABRAS_AFUERA = /proveedor|extern|afuera|cloudflare|twilio|tercer|noticia|paro|corte/i;
function salaElegir(pregunta, disponibles) {
  const out = ['estado_incidente', 'tareas_incidente'];
  if (SALA_PALABRAS_GUIA.test(pregunta)) out.push('guia_diagnostico');
  if (SALA_PALABRAS_AFUERA.test(pregunta)) out.push('contexto_externo');
  if (SALA_PALABRAS_TAREAS.test(pregunta)) out.push('tareas_salas');
  if (SALA_PALABRAS_MIS.test(pregunta)) out.push('mis_alertas', 'alertas_abiertas');   // cada perfil tiene una de las dos
  if (SALA_PALABRAS_PARECIDAS.test(pregunta)) out.push('casos_parecidos');
  return out.filter((n) => disponibles.includes(n)).slice(0, 5);
}
const SALA_GUIA_LIBRE = 'Respondé con estos datos de la sala, en pocas frases y en español. No digas que vas a consultar algo: ya lo tenés. Si falta un dato, decí cuál. ' +
  'Si preguntan si conviene escalar: decidilo con las tareas hechas y abiertas, las dependencias de la guía (por ejemplo, el proveedor) y, si está, lo de afuera; si conviene, proponelo con sugerir_accion (tipo escalar). ' +
  'Escalar crea una tarea para una persona de Soporte de Helios, que es quien contacta al proveedor: las personas de Soporte no son el proveedor. ' +
  'No escribas la llamada a sugerir_accion en el texto ni pidas tocar "Hacerlo": el botón aparece solo.';
// "¿Escalo…?": botón armado por el servidor si el modelo no lo dejó (a la persona de Soporte con menos tareas abiertas en salas)
function salaProponerEscalar(d, incidenteId, motivoModelo) {
  const t = (d && d.tareas_incidente) || {}, e = (d && d.estado_incidente) || {};
  const personas = ((t.opciones_asignacion || {}).personas_soporte || []).slice().sort((x, y) => x.tareas_abiertas - y.tareas_abiertas);
  if (!personas.length) return null;
  const situacion = (e.sala || 'La sala') + ' sigue ' + String(e.estado || 'abierta').toLowerCase() + (e.problema_desde ? '; el problema empezó ' + e.problema_desde : '') + '.';
  return { tipo: 'escalar', incidente_id: incidenteId, usuario_id: personas[0].usuario_id,
    motivo: 'Queda como tarea para una persona de Soporte, que contacta al proveedor y anota la respuesta en la sala.',
    comentario: motivoModelo ? motivoModelo + ' ' + situacion : situacion + ' Hay que escalarlo al proveedor.' };
}
// El modelo anunció que iba a consultar algo en vez de pedir la herramienta
const ASIST_PROMESA = /\b(d[eé]jame|voy a|necesito|tengo que|tendr[ií]a que|deber[ií]a|perm[ií]teme|d[eé]jenme|vamos a)\s+(consultar|revisar|buscar|usar|chequear|verificar|mirar|ver)\b|necesito que (me )?(pidas|pidan|consultes|dejes|uses)|me (pidas|pida|pidan) que (consulte|use|revise|mire)|(consult|revis)e? (las|los|la|el) (opciones|carga|datos)\b.{0,60}para (poder )?(decirte|responder|contestarte)/i;

// ---------- Propuestas de la sala ----------
const SALA_ACCIONES = {
  asignar_tarea: { titulo: 'Asignar una tarea en la sala' },
  escalar: { titulo: 'Escalar el incidente' },
  comunicar: { titulo: 'Comunicar el incidente' },
};
for (const k of Object.keys(SALA_ACCIONES)) ASIST_ACCIONES[k] = { ok: (yo) => puede(yo, 'sala_crisis_dirigir'), titulo: SALA_ACCIONES[k].titulo, soloSala: true };
async function asistValidarAccionSala(env, yo, a) {
  const tipo = String(a.tipo);
  if (!puede(yo, 'sala_crisis_dirigir')) return { error: 'Esa acción no está disponible para tu perfil.' };
  const id = aId(a.incidente_id);
  if (!id) return { error: 'Para ' + tipo + ' hace falta el incidente_id de la sala.' };
  const rol = await rolEnIncidente(env, yo, id);
  if (rol.error || !rol.dirige) return { error: 'Esa sala no está disponible.' };
  if (!rol.abierto) return { error: 'La sala está cerrada.' };
  const cod = imCodigo(id);
  const p = { tipo, incidente_id: id, titulo: SALA_ACCIONES[tipo].titulo, alerta: cod + ' · ' + rol.inc.titulo, motivo: a.motivo ? String(a.motivo).slice(0, 300) : '',
    comentario: a.comentario ? String(a.comentario).slice(0, 1500) : '' };
  if (tipo === 'comunicar') {
    const al = await env.DB.prepare(`SELECT ia.alerta_id FROM incidente_alertas ia JOIN alertas_historico h ON h.alerta_id = ia.alerta_id
      WHERE ia.incidente_id = ?1 ORDER BY CASE WHEN h.estado = 'RESUELTA' THEN 1 ELSE 0 END, ia.sumada LIMIT 1`).bind(id).first();
    if (!al) return { error: 'La sala no tiene alertas para comunicar.' };
    p.alerta_id = al.alerta_id; p.clave = 'comunicar' + id;
    if (!p.comentario) p.comentario = 'Incidente ' + cod + ': ' + rol.inc.titulo + '. Estado: ' + IM_ESTADO_TXT[rol.inc.estado].toLowerCase() + '. Estamos trabajando para restablecer el servicio.';
    return p;
  }
  const d = await destinoTarea(env, { responsable_usuario_id: a.usuario_id, equipo_id: a.equipo_id });
  if (d.error) return { error: 'Para ' + (tipo === 'escalar' ? 'escalar' : 'asignar') + ' hace falta una persona de Soporte (usuario_id) o un equipo (equipo_id) que exista; usá tareas_incidente.' };
  const r = await env.DB.batch([env.DB.prepare('SELECT nombre FROM usuarios WHERE id = ?1').bind(d.uid || 0), env.DB.prepare('SELECT nombre FROM equipos WHERE id = ?1').bind(d.eid || 0)]);
  p.usuario_id = d.uid; p.equipo_id = d.eid;
  p.destino = [(r[0].results[0] || {}).nombre, (r[1].results[0] || {}).nombre ? 'equipo ' + r[1].results[0].nombre : null].filter(Boolean).join(' · ');
  if (tipo === 'asignar_tarea') {
    const t = String(a.titulo_tarea || a.titulo || '').trim().slice(0, 160);
    if (t.length < 4) return { error: 'Para asignar una tarea hace falta titulo_tarea (qué hay que hacer).' };
    p.tarea = t; p.alerta = cod + ' · ' + t; p.clave = 'tarea' + id + ':' + t.toLowerCase();
    const comp = aId(a.componente_id);
    if (comp && (await env.DB.prepare('SELECT 1 FROM componentes_infraestructura WHERE id = ?1').bind(comp).first())) p.componente_id = comp;
  } else {
    if (!p.comentario) p.comentario = p.motivo;
    if (String(p.comentario || '').trim().length < 5) return { error: 'Para escalar hace falta el motivo.' };
    p.clave = 'escalar' + id + ':' + (d.uid || '') + ':' + (d.eid || '');
  }
  return p;
}
// "¿Qué reviso primero?": el servidor arma hasta 2 tareas para los componentes que nadie revisó ni está revisando, a la persona de Soporte con menos tareas
function salaProponerTareas(d, incidenteId) {
  const g = d.guia_diagnostico || {}, t = d.tareas_incidente || {};
  const op = t.opciones_asignacion; if (!op) return [];
  const ocupados = new Set(t.componentes_ya_revisados_o_en_revision || []);
  const personas = (op.personas_soporte || []).slice().sort((x, y) => x.tareas_abiertas - y.tareas_abiertas);
  const out = [];
  for (const c of g.componentes || []) {
    if (out.length >= 2 || ocupados.has(c.componente_id) || !personas.length) continue;
    const p = personas[out.length % personas.length];
    out.push({ tipo: 'asignar_tarea', incidente_id: incidenteId, titulo_tarea: 'Revisar ' + c.componente, componente_id: c.componente_id, usuario_id: p.usuario_id,
      comentario: c.que_revisar || '', motivo: 'Es uno de los componentes de los que depende el servicio y todavía nadie lo revisó.' });
  }
  return out;
}
const SALA_SUGERENCIAS = [
  { id: 'sala_como_vamos', texto: '¿Cómo vamos con este incidente?', herramientas: ['estado_incidente', 'tareas_incidente'],
    guia: 'En 5 renglones como mucho: estado y desde cuándo (una frase), qué se sabe hasta ahora según las tareas hechas, qué falta (tareas abiertas y quién las tiene) y si algo está demorado. Si no hay tareas, decí que todavía no se asignó ninguna. No inventes causas.' },
  { id: 'sala_que_reviso', texto: '¿Qué reviso primero?', herramientas: ['guia_diagnostico', 'tareas_incidente'],
    guia: 'Ordená qué revisar primero: si un antecedente tuvo la causa en un componente de esta guía, empezá por ese y nombrá el antecedente (código y causa) en una frase. Para cada componente (como mucho 3), una frase con qué mirar. No repitas lo que ya se revisó o tiene una tarea abierta (componentes_ya_revisados_o_en_revision). Si te dejamos botones para asignar tareas, decí "Te dejo los botones para asignarlas".',
    proponer: (d, id) => salaProponerTareas(d, id) },
  { id: 'sala_demorado', texto: '¿Qué está demorado?', herramientas: ['tareas_incidente'],
    guia: 'Mirá cuantas.demoradas. Si es 0, decí "No hay nada demorado." y en una frase cuántas tareas siguen abiertas. Si hay, listá cada una con quién la tiene y cuánto lleva, y sugerí en una frase pedir novedades o escalar.' },
];
const ASIST_REGLA_SALA = '9. Estás dentro de una sala de crisis (incidente_id {ID}). Usá estado_incidente, tareas_incidente y guia_diagnostico con ese incidente_id. Si conviene asignar una tarea, escalar o comunicar, proponelo con sugerir_accion (tipo asignar_tarea con titulo_tarea y usuario_id o equipo_id de opciones_asignacion; escalar con usuario_id o equipo_id y el motivo en comentario; comunicar con el mensaje en comentario). Nunca digas que ya se hizo.';

async function rutasAsistente(env, request, ruta, yo) {
  if (!ruta.startsWith('/api/asistente')) return null;
  if (!puede(yo, 'asistente')) return jsonError('Tu perfil no tiene el asistente.', 403);
  const m = request.method;
  if (m === 'GET' && ruta === '/api/asistente') {
    let uso = null;
    try { uso = await asistUso(env, yo); } catch (e) { /* sin la tabla asistente_uso */ }
    return okJson({ disponible: !!(env.AI && uso), perfil: yo.perfil, nombre: yo.nombre.split(' ')[0],
      sugerencias: (ASIST_SUGERENCIAS[yo.perfil] || []).map((s) => ({ id: s.id, texto: s.texto })), restantes: uso ? uso.restantes : 0,
      sugerencias_sala: puede(yo, 'sala_crisis') ? SALA_SUGERENCIAS.map((s) => ({ id: s.id, texto: s.texto })) : [],
      motivo: !env.AI ? 'Falta conectar Workers AI al Worker (enlace "AI").' : !uso ? 'Falta crear la tabla asistente_uso (script 11).' : null });
  }
  if (m === 'POST' && ruta === '/api/asistente') {
    if (!env.AI) return jsonError('El asistente todavía no está configurado: falta conectar Workers AI al Worker (enlace "AI").', 503);
    const b = await leerCuerpo(request);
    // Dentro de una sala de crisis (parche 69): se valida con la misma regla de la sala y se usan sus preguntas sugeridas
    const incidenteId = b.incidente_id == null || b.incidente_id === '' ? null : aId(b.incidente_id);
    if (b.incidente_id != null && b.incidente_id !== '' && !incidenteId) return jsonError('Sala inválida.', 400);
    if (incidenteId) {
      if (!puede(yo, 'sala_crisis')) return jsonError('Tu perfil no tiene acceso a la sala de crisis.', 403);
      let rolSala;
      try { rolSala = await rolEnIncidente(env, yo, incidenteId); } catch (e) { if (/no such table/i.test(e.message)) return jsonError(FALTA_SCRIPT_24, 503); throw e; }
      if (rolSala.error) return rolSala.error;
    }
    const salaSug = b.sugerencia && /^sala_/.test(String(b.sugerencia)) ? SALA_SUGERENCIAS.find((s) => s.id === String(b.sugerencia)) : null;
    if (salaSug && !incidenteId) return jsonError('Esa pregunta es de una sala de crisis.', 400);
    const sugerencia = salaSug ? Object.assign({}, salaSug, { args: Object.fromEntries(salaSug.herramientas.map((n) => [n, { incidente_id: incidenteId }])),
        proponer: salaSug.proponer ? (d) => salaSug.proponer(d, incidenteId) : null })
      : b.sugerencia ? (ASIST_SUGERENCIAS[yo.perfil] || []).find((s) => s.id === String(b.sugerencia)) : null;
    if (b.sugerencia && !sugerencia) return jsonError('Esa pregunta no está disponible para tu perfil.', 400);
    const alertaId = b.alerta_id ? String(b.alerta_id).toLowerCase() : null;
    if (alertaId && !/^[0-9a-f]{32}$/.test(alertaId)) return jsonError('Alerta inválida.', 400);
    // Preguntas siguientes de una conversación que se abrió con «¿Qué está pasando?» de una alerta: la página manda cuál es
    const alertaCtx = !alertaId && !sugerencia && b.alerta_contexto ? String(b.alerta_contexto).toLowerCase() : null;
    if (alertaCtx && !/^[0-9a-f]{32}$/.test(alertaCtx)) return jsonError('Alerta inválida.', 400);
    let pregunta = sugerencia ? sugerencia.texto : alertaId ? '¿Qué está pasando con esta alerta, qué revisaría primero y qué sugerís hacer?' : String(b.pregunta || '').trim();
    if (!pregunta) return jsonError('Escribí una pregunta.', 400);
    if (pregunta.length > ASIST_MAX_PREGUNTA) return jsonError('La pregunta es muy larga (máximo ' + ASIST_MAX_PREGUNTA + ' caracteres).', 400);
    // Saludos y agradecimientos sueltos: respuesta fija, sin modelo, sin gastar del límite y sin registro (parche 74)
    if (!sugerencia && !alertaId) { const corta = asistCortesia(pregunta); if (corta) return okJson({ respuesta: corta, acciones: [], herramientas: [], sin_ia: true, restantes: null }); }
    // Límite de uso: por persona y por hora, y en total por día (cupo gratuito de Workers AI)
    let uso;
    try { uso = await asistUso(env, yo); }
    catch (e) { return jsonError('Falta crear la tabla del asistente: corran 11_asistente_d1.txt en la consola de D1.', 500); }
    if (uso.mias >= asistPorHora(env)) return jsonError('Llegaste al máximo de ' + asistPorHora(env) + ' preguntas por hora. Probá en un rato.', 429);
    if (uso.dia >= asistPorDia(env)) return jsonError('El asistente llegó al máximo de preguntas de hoy. Mañana vuelve a estar disponible.', 429);
    await env.DB.batch([
      env.DB.prepare('INSERT INTO asistente_uso (hora, usuario_id, preguntas) VALUES (?1, ?2, 1) ON CONFLICT (hora, usuario_id) DO UPDATE SET preguntas = preguntas + 1').bind(uso.hora, yo.id),
      env.DB.prepare('INSERT INTO auditoria (usuario_id, accion, detalle) VALUES (?1, ?2, ?3)').bind(yo.id, 'ASISTENTE', (alertaId ? '[alerta ' + alertaId.slice(0, 8) + '] ' : '') + (incidenteId ? '[' + imCodigo(incidenteId) + '] ' : '') + pregunta.slice(0, 300)),
    ]);
    try {
      const r = await asistResponder(env, yo, { pregunta, historia: sugerencia || alertaId ? [] : asistHistoria(b.historia), sugerencia, alerta_id: alertaId, alerta_contexto: alertaCtx, incidente_id: incidenteId });
      return okJson(Object.assign(r, { restantes: Math.max(0, uso.restantes - 1) }));
    } catch (e) {
      console.error('Asistente: ' + e.message);
      return jsonError('El asistente no pudo responder ahora (' + String(e.message || e).slice(0, 120) + '). Probá de nuevo en un momento.', 502);
    }
  }
  return jsonError('Ruta no encontrada: ' + ruta, 404);
}

// ============================================================================
// CONTEXTO EXTERNO PARA EL ASISTENTE (parche 29)
// ----------------------------------------------------------------------------
// Lo que pasa afuera y puede afectar la operación, para que el asistente lo cruce con las alertas:
//   1. Calendario (gratis, sale de la base): feriados, fines de semana largos, primeros días hábiles del mes
//      (cobro de sueldos), aguinaldo y eventos comerciales cargados por el Administrador.
//   2. Proveedores: incidentes abiertos y mantenimientos programados de servicios que publican su estado
//      (páginas de estado tipo Statuspage). Por defecto Cloudflare y Twilio; se cambia con la variable
//      CONTEXTO_PROVEEDORES = [{"nombre":"…","base":"https://…"}].
//   3. Noticias de Argentina de las últimas 48 h que pueden afectar pagos y transferencias (buscador abierto GDELT).
//      Se cambia la búsqueda con CONTEXTO_NOTICIAS_CONSULTA. Con CONTEXTO_EXTERNO = "apagado" no se consulta nada de afuera.
//   4. Eventos comerciales (Hot Sale, CyberMonday, Black Friday…): tabla eventos_comerciales, Administración > Umbrales.
//
// Cuidado del plan gratuito:
//   - Proveedores y noticias se consultan como mucho una vez por hora y se guardan en contexto_externo
//     (1 fila por fuente): leerlos cuesta 1 consulta; actualizarlos, 1 escritura por fuente y hora.
//   - Solo se consultan cuando alguien le pregunta al asistente algo de este tema (no hay cron).
//   - Cada pedido externo tiene 5 segundos de tope; si falla, se usa lo último guardado y se avisa.
// Tablas: contexto_externo y eventos_comerciales (script 12_contexto_externo_d1.txt).
// ============================================================================
const CONTEXTO_MINUTOS = 60;
const CONTEXTO_TOPE_MS = 5000;
const CONTEXTO_PROVEEDORES_FABRICA = [
  { nombre: 'Cloudflare', base: 'https://www.cloudflarestatus.com' },
  { nombre: 'Twilio (SMS y códigos de verificación)', base: 'https://status.twilio.com' },
];
// Noticias: primero Google Noticias (Argentina, en español; responde rápido), y si falla, GDELT (más lento)
const CONTEXTO_NOTICIAS_FABRICA = '"paro bancario" OR "home banking" OR "billeteras virtuales" OR "Mercado Pago" OR "BCRA" OR "transferencias" OR "corte de luz" OR "apagón" OR "ciberataque" OR "caída del sistema"';
const CONTEXTO_NOTICIAS_GDELT = '("paro bancario" OR "caída del sistema" OR "home banking" OR "billeteras virtuales" OR "Mercado Pago" OR "BCRA" OR "corte de luz" OR "apagón" OR "ciberataque" OR "transferencias inmediatas") sourcecountry:AR sourcelang:spanish';
const CTX_IMPACTO = { none: 'sin impacto', minor: 'menor', major: 'importante', critical: 'grave', maintenance: 'mantenimiento' };
const CTX_ESTADO = { investigating: 'investigando', identified: 'causa identificada', monitoring: 'en observación', scheduled: 'programado', in_progress: 'en curso', verifying: 'verificando' };
const CTX_DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];

const ctxDia = (iso) => iso.slice(8, 10) + '/' + iso.slice(5, 7);
const ctxSumar = (iso, n) => new Date(Date.parse(iso + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const ctxDow = (iso) => new Date(iso + 'T12:00:00Z').getUTCDay();
function ctxHoraArg(iso) {
  const t = Date.parse(iso); if (isNaN(t)) return null;
  const d = new Date(t - 3 * 3600000).toISOString();
  return ctxDia(d.slice(0, 10)) + ' ' + d.slice(11, 16);
}
async function ctxTraer(url, texto, tope) {
  const r = await fetch(url, { headers: { accept: texto ? 'application/rss+xml, text/xml' : 'application/json', 'user-agent': 'Helios-Monitoreo/1.0' }, signal: AbortSignal.timeout(tope || CONTEXTO_TOPE_MS) });
  if (!r.ok) throw new Error('respondió ' + r.status);
  const t = await r.text();
  if (texto) return t;
  try { return JSON.parse(t); } catch (e) { throw new Error('no devolvió datos válidos'); }
}
// Título en español: lo arma el servidor a partir de palabras clave (el modelo no siempre traducía).
// Si el título ya está en español, queda como está. El original queda en titulo_original.
const CTX_ES = /\b(de|del|en|los|las|para|por|con|demoras?|caída|fallas?|errores|mantenimiento)\b/i;
function ctxTituloEs(t, tipo) {
  t = String(t || '');
  if (CTX_ES.test(t) && !/\b(the|with|for|and|of|on|to|in)\b/i.test(t)) return t;
  const queTipo = /maintenance/i.test(t) || tipo === 'Mantenimiento programado' ? 'Mantenimiento programado' : /outage|\bdown\b|unavailable|not (working|available)/i.test(t) ? 'Caída' : /error|fail/i.test(t) ? 'Más errores' :
    /latenc|slow|delay/i.test(t) ? 'Demoras' : /degrad/i.test(t) ? 'Funcionamiento degradado' : /not producing|missing|not (being )?(sent|delivered)/i.test(t) ? 'Falla' : 'Problemas';
  const dondeTxt = /workers ai/i.test(t) ? 'en Workers AI (el asistente de Helios)' : /\bD1\b/.test(t) ? 'en D1 (la base de Helios)' :
    /workers?\b[\s\S]*startup|startup[\s\S]*workers?\b/i.test(t) ? 'al iniciar Workers (donde corre Helios)' : /\bworkers?\b/i.test(t) ? 'en Workers (donde corre Helios)' :
    /\bdns\b/i.test(t) ? 'en el DNS' : /verif|otp|2fa|lookup/i.test(t) ? 'en los códigos de verificación' : /\bsms\b/i.test(t) ? 'en el envío de SMS' :
    /voice|call/i.test(t) ? 'en las llamadas' : /e-?mail/i.test(t) ? 'en el envío de correos' : /dashboard/i.test(t) ? 'en el panel' : /\bapi\b/i.test(t) ? 'en la API' : '';
  const lugar = /argentin|buenos aires|\bEZE\b/i.test(t) ? ' en Argentina' : /latin ?america|south america|\blatam\b/i.test(t) ? ' en Latinoamérica' : '';
  return (queTipo + (dondeTxt ? ' ' + dondeTxt : '') + lugar).trim();
}
const ctxEntidades = (t) => String(t || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
function ctxProveedores(env) {
  try {
    const l = env.CONTEXTO_PROVEEDORES ? JSON.parse(env.CONTEXTO_PROVEEDORES) : CONTEXTO_PROVEEDORES_FABRICA;
    return (Array.isArray(l) ? l : []).filter((p) => p && typeof p.nombre === 'string' && /^https:\/\/[a-z0-9.-]+$/i.test(String(p.base || '').replace(/\/$/, '')))
      .slice(0, 6).map((p) => ({ nombre: p.nombre.slice(0, 60), base: p.base.replace(/\/$/, '') }));
  } catch (e) { return CONTEXTO_PROVEEDORES_FABRICA; }
}

// ---------- Fuentes externas (con caché de una hora en contexto_externo) ----------
async function ctxBajarProveedores(env, ahoraMs) {
  const out = [], errores = [];
  await Promise.all(ctxProveedores(env).map(async (p) => {
    try {
      const [inc, man] = await Promise.all([ctxTraer(p.base + '/api/v2/incidents/unresolved.json'), ctxTraer(p.base + '/api/v2/scheduled-maintenances/upcoming.json').catch(() => ({}))]);
      for (const i of (inc.incidents || []).slice(0, 12))
        out.push({ proveedor: p.nombre, tipo: 'Incidente', titulo: String(i.name || '').slice(0, 160), titulo_es: ctxTituloEs(i.name, 'Incidente'), impacto: CTX_IMPACTO[i.impact] || i.impact, estado: CTX_ESTADO[i.status] || i.status,
          desde: ctxHoraArg(i.created_at), afecta: (i.components || []).slice(0, 8).map((c) => c.name).join(', ') || undefined, link: i.shortlink || undefined });
      for (const m of (man.scheduled_maintenances || []).filter((m) => Date.parse(m.scheduled_for) - ahoraMs < 48 * 3600000).slice(0, 12))
        out.push({ proveedor: p.nombre, tipo: 'Mantenimiento programado', titulo: String(m.name || '').slice(0, 160), titulo_es: ctxTituloEs(m.name, 'Mantenimiento programado'), desde: ctxHoraArg(m.scheduled_for), hasta: ctxHoraArg(m.scheduled_until), link: m.shortlink || undefined });
    } catch (e) { errores.push(p.nombre + ': ' + (e.name === 'TimeoutError' ? 'no respondió a tiempo' : e.message)); }
  }));
  return { consultados: ctxProveedores(env).map((p) => p.nombre), novedades: out, errores };
}
async function ctxBajarNoticias(env, ahoraMs) {
  const vistos = new Set(), out = [];
  const sumar = (titulo, medio, fechaIso, link) => {
    const t = String(titulo || '').replace(/\s+/g, ' ').trim(), k = t.toLowerCase().slice(0, 60);
    if (!t || vistos.has(k) || !/^https:\/\//.test(link || '') || out.length >= 8) return;
    if (fechaIso && ahoraMs - Date.parse(fechaIso) > 48 * 3600000) return;
    vistos.add(k); out.push({ titulo: t.slice(0, 160), medio, fecha: fechaIso ? ctxHoraArg(fechaIso) : null, link });
  };
  try {
    const q = (env.CONTEXTO_NOTICIAS_CONSULTA || CONTEXTO_NOTICIAS_FABRICA) + ' when:2d';
    const xml = await ctxTraer('https://news.google.com/rss/search?q=' + encodeURIComponent(q) + '&hl=es-419&gl=AR&ceid=AR:es-419', true);
    for (const m of xml.matchAll(/<item>([\s\S]*?)<\/item>/g)) {
      const it = m[1], g = (re) => { const x = it.match(re); return x ? ctxEntidades(x[1]) : ''; };
      const medio = g(/<source[^>]*>([\s\S]*?)<\/source>/), fecha = Date.parse(g(/<pubDate>([\s\S]*?)<\/pubDate>/));
      let titulo = g(/<title>([\s\S]*?)<\/title>/);
      if (medio && titulo.endsWith(' - ' + medio)) titulo = titulo.slice(0, -(medio.length + 3));
      sumar(titulo, medio || 'Google Noticias', isNaN(fecha) ? null : new Date(fecha).toISOString(), g(/<link>([\s\S]*?)<\/link>/));
    }
    return { noticias: out, fuente: 'Google Noticias (Argentina)' };
  } catch (e) {
    const j = await ctxTraer('https://api.gdeltproject.org/api/v2/doc/doc?query=' + encodeURIComponent(CONTEXTO_NOTICIAS_GDELT) + '&mode=ArtList&format=json&timespan=2d&sort=DateDesc&maxrecords=20', false, 8000);
    for (const a of j.articles || []) {
      const s = String(a.seendate || '');   // 20261113T120000Z
      sumar(a.title, a.domain, s.length >= 13 ? s.slice(0, 4) + '-' + s.slice(4, 6) + '-' + s.slice(6, 8) + 'T' + s.slice(9, 11) + ':' + s.slice(11, 13) + ':00Z' : null, a.url);
    }
    return { noticias: out, fuente: 'GDELT (Google Noticias no respondió)' };
  }
}
async function ctxFuente(env, filas, fuente, bajar) {
  const ahoraMs = Date.now();
  const f = filas.find((x) => x.fuente === fuente);
  // Si la última vez falló, se vuelve a probar a los 10 minutos (no a la hora)
  const fallo = f && (f.error || /"errores":\["/.test(f.contenido));   // también si algún proveedor no respondió
  if (f && ahoraMs - Date.parse(f.actualizado) < (fallo ? 10 : CONTEXTO_MINUTOS) * 60000) return { ...JSON.parse(f.contenido), actualizado: ctxHoraArg(f.actualizado), error: f.error || undefined };
  if (String(env.CONTEXTO_EXTERNO || '').toLowerCase() === 'apagado') return { apagado: true };
  let contenido, error = null;
  try { contenido = await bajar(env, ahoraMs); }
  catch (e) { error = e.name === 'TimeoutError' ? 'no respondió a tiempo' : e.message; contenido = f ? JSON.parse(f.contenido) : {}; }
  const ahoraIso = new Date(ahoraMs).toISOString();
  // Aunque falle se guarda la hora: así no se reintenta en cada pregunta (vuelve a probar en una hora)
  try {
    await env.DB.prepare(`INSERT INTO contexto_externo (fuente, actualizado, contenido, error) VALUES (?1, ?2, ?3, ?4)
      ON CONFLICT (fuente) DO UPDATE SET actualizado = excluded.actualizado, contenido = excluded.contenido, error = excluded.error`)
      .bind(fuente, ahoraIso, JSON.stringify(contenido).slice(0, 20000), error).run();
  } catch (e) { console.error('Contexto externo, guardar ' + fuente + ': ' + e.message); }
  return { ...contenido, actualizado: ctxHoraArg(ahoraIso), error: error || undefined };
}

// ---------- Qué novedades de proveedores importan (se filtra al leer, así también vale para lo ya guardado) ----------
// Helios corre en Cloudflare Workers y D1: un incidente ahí afecta a la plataforma misma. Lo de otros países no importa.
const CTX_AR_TITULO = /argentin|buenos aires|\bEZE\b/i;
const CTX_ARGENTINA = /argentin|buenos aires|\bEZE\b|latin ?america|\blatam\b|south america|sudam[eé]rica|am[eé]rica latina/i;
const CTX_HELIOS = /\bworkers?\b|\bD1\b|workers ai|\bKV\b|durable objects/i;
// Partes de Cloudflare que Helios no usa: aunque digan "Workers", no afectan a la plataforma
const CTX_NO_HELIOS = /subscription|\bevents?\b|\bbuilds?\b|\blogs?\b|logpush|analytics|\bpages\b|queues|\bR2\b|images|stream|observability|\btail\b|workflows|containers|vectorize|hyperdrive|browser rendering|email routing|zaraz/i;
const CTX_OTRO_PAIS = /\b(UK|U\.K\.|United Kingdom|England|Ireland|Philippines|Costa Rica|India|Russia|Italy|Singapore|Japan|China|Korea|Taiwan|Hong Kong|Germany|France|Spain|Portugal|Netherlands|Belgium|Switzerland|Austria|Poland|Czech|Romania|Hungary|Greece|Ukraine|Turkey|Sweden|Norway|Denmark|Finland|Mexico|Colombia|Peru|Chile|Brazil|Uruguay|Paraguay|Bolivia|Ecuador|Venezuela|Guatemala|Panama|Dominican|Puerto Rico|Canada|United States|USA|US|Australia|New Zealand|Indonesia|Vietnam|Thailand|Malaysia|Pakistan|Bangladesh|Saudi|UAE|Emirates|Israel|Egypt|Nigeria|Kenya|South Africa|Europe|Asia|APAC|EMEA|North America)\b|^[A-Z]{3} \(/;
function ctxRelevantes(prov) {
  const out = { afectan_a_helios: [], argentina_o_region: [], globales_importantes: [], otros_paises_descartados: 0, menores_sin_lugar_descartados: 0 };
  for (const n0 of prov.novedades || []) {
    const n = n0.titulo_es ? n0 : { ...n0, titulo_es: ctxTituloEs(n0.titulo, n0.tipo) };
    const t = n.titulo + ' ' + (n.afecta || '');
    // Si el título nombra otro país (aunque el componente diga "Latin America"), no es de Argentina
    if (CTX_OTRO_PAIS.test(n.titulo) && !CTX_AR_TITULO.test(n.titulo)) { out.otros_paises_descartados++; continue; }
    if (/^Cloudflare/.test(n.proveedor) && CTX_HELIOS.test(t) && !CTX_NO_HELIOS.test(t) && !(CTX_OTRO_PAIS.test(t) && !CTX_ARGENTINA.test(t))) out.afectan_a_helios.push(n);
    else if (CTX_ARGENTINA.test(t)) out.argentina_o_region.push(n);
    else if (CTX_OTRO_PAIS.test(t)) out.otros_paises_descartados++;
    else if (n.tipo === 'Incidente' && (n.impacto === 'importante' || n.impacto === 'grave')) out.globales_importantes.push(n);
    else out.menores_sin_lugar_descartados++;
  }
  return out;
}

// ---------- Calendario (sale de la base: feriados y eventos_comerciales) ----------
function ctxCalendario(hoy, dias, feriados, eventos) {
  const fer = new Map(feriados.map((f) => [f.fecha, f.nombre]));
  const libre = (d) => ctxDow(d) === 0 || ctxDow(d) === 6 || fer.has(d);
  const habilDelMes = (d) => {   // 1 = primer día hábil del mes; 0 si no es hábil
    if (libre(d)) return 0;
    let n = 0; for (let x = d.slice(0, 8) + '01'; x <= d; x = ctxSumar(x, 1)) if (!libre(x)) n++;
    return n;
  };
  const out = [];
  for (let i = 0; i < dias; i++) {
    const d = ctxSumar(hoy, i), notas = [];
    if (fer.has(d)) notas.push('Feriado: ' + fer.get(d) + '. Se espera tráfico como un domingo (o nada, en los servicios que silencian feriados).');
    if (libre(d)) {
      let a = d, b = d; while (libre(ctxSumar(a, -1))) a = ctxSumar(a, -1); while (libre(ctxSumar(b, 1))) b = ctxSumar(b, 1);
      const largo = Math.round((Date.parse(b) - Date.parse(a)) / 86400000) + 1;
      if (largo >= 3) notas.push('Fin de semana largo (' + largo + ' días, del ' + ctxDia(a) + ' al ' + ctxDia(b) + '): menos operación de empresas; el día hábil siguiente suele venir cargado.');
    } else if (libre(ctxSumar(d, -1))) {
      let a = ctxSumar(d, -1), n = 0; while (libre(a)) { n++; a = ctxSumar(a, -1); }
      if (n >= 3) notas.push('Primer día hábil después de un fin de semana largo: suele haber más transferencias y pagos acumulados.');
    }
    const h = habilDelMes(d);
    if (h >= 1 && h <= 4) notas.push(h + '.º día hábil del mes: cobro de sueldos (hasta el 4.º día hábil). Suben transferencias, pagos de servicios y recargas.');
    if (d.slice(5) === '06-30' || d.slice(5) === '12-18') notas.push('Vence el pago del aguinaldo: más movimiento de sueldos y transferencias.');
    for (const e of eventos.filter((e) => e.fecha_desde <= d && e.fecha_hasta >= d))
      notas.push('Evento comercial: ' + e.nombre + (e.cliente_id || e.servicio_id ? ' (' + [e.cliente_id, e.servicio_id].filter(Boolean).join(', ') + ')' : '') + '. ' +
        (e.efecto_esperado === 'MENOS_TRAFICO' ? 'Se espera menos tráfico.' : 'Se espera más tráfico de lo normal.') + (e.nota ? ' ' + e.nota : ''));
    out.push({ fecha: ctxDia(d), dia: CTX_DIAS[ctxDow(d)], cuando: i === 0 ? 'hoy' : i === 1 ? 'mañana' : 'en ' + i + ' días', notas: notas.length ? notas : ['Día común: sin feriados, eventos ni fechas de cobro.'] });
  }
  return out;
}

async function contextoExterno(env, yo, a) {
  const dias = Math.min(7, Math.max(1, Number(a && a.dias) || 3));
  const ah = await asistAhora(env);
  // Fecha de Argentina. Con el reloj de la demo puesto, el calendario usa la fecha real (como proveedores y noticias),
  // salvo CONTEXTO_CALENDARIO = "demo" (para mostrar en una demo cómo avisa un feriado en la fecha simulada).
  const usarDemo = ah.simulado && String(env.CONTEXTO_CALENDARIO || '').toLowerCase() === 'demo';
  const hoy = new Date((usarDemo || !ah.simulado ? Date.parse(ah.ahora) : Date.now()) - 3 * 3600000).toISOString().slice(0, 10);
  const desde = ctxSumar(hoy.slice(0, 8) + '01', -7) < ctxSumar(hoy, -7) ? ctxSumar(hoy.slice(0, 8) + '01', -7) : ctxSumar(hoy, -7);
  const hasta = ctxSumar(hoy, dias + 7);
  const q = [
    env.DB.prepare('SELECT fecha, nombre FROM feriados WHERE fecha >= ?1 AND fecha <= ?2 ORDER BY fecha').bind(desde, hasta),
    env.DB.prepare('SELECT nombre, fecha_desde, fecha_hasta, cliente_id, servicio_id, efecto_esperado, nota FROM eventos_comerciales WHERE fecha_hasta >= ?1 AND fecha_desde <= ?2 ORDER BY fecha_desde LIMIT 20').bind(hoy, ctxSumar(hoy, dias - 1)),
    env.DB.prepare('SELECT fuente, actualizado, contenido, error FROM contexto_externo'),
  ];
  if (puede(yo, 'tablero')) q.push(env.DB.prepare("SELECT cliente_id, servicio_id, criticidad, silenciar_feriados FROM umbrales_config WHERE criticidad = 'ALTA' OR silenciar_feriados = 1 LIMIT 40"));
  const r = await env.DB.batch(q);
  const [proveedores, noticias] = await Promise.all([
    ctxFuente(env, r[2].results, 'proveedores', ctxBajarProveedores),
    ctxFuente(env, r[2].results, 'noticias', ctxBajarNoticias),
  ]);
  const rel = proveedores.apagado ? null : ctxRelevantes(proveedores);
  // Los enlaces no van al modelo (los de Google Noticias tienen ~400 caracteres y los copiaba mal o cortaba la respuesta):
  // cada novedad lleva un código corto ([E1], [N1]) y el servidor lo cambia por el enlace real antes de mostrar la respuesta.
  const enlaces = {}, cuenta = { E: 0, N: 0 };
  const conRef = (n, pre) => { if (!n.link) return n; const k = pre + (++cuenta[pre]); enlaces[k] = n.link; const c = { ...n, ref: '[' + k + ']' }; delete c.link; return c; };
  if (rel) for (const g of ['afectan_a_helios', 'argentina_o_region', 'globales_importantes']) rel[g] = rel[g].map((n) => conRef(n, 'E'));
  const corto = (x) => String(x).replace(/\s*\(.*\)\s*/g, '');
  const nov = (n) => corto(n.proveedor) + ': ' + (n.titulo_es || n.titulo) + (n.impacto ? ' (impacto ' + n.impacto + (n.estado ? ', ' + n.estado : '') + ')' : '') + (n.desde ? ', desde ' + n.desde : '') + (n.hasta ? ' hasta ' + n.hasta : '') + (n.ref ? ' ' + n.ref : '');
  const calendario = ctxCalendario(hoy, dias, r[0].results, r[1].results);
  const puntos = [];
  if (rel && rel.afectan_a_helios.length) puntos.push('HELIOS MISMO (corre en Cloudflare Workers y D1, puede fallar la plataforma): ' + rel.afectan_a_helios.map(nov).join(' | '));
  puntos.push('CALENDARIO: ' + calendario.map((c) => c.cuando + ' (' + c.dia + ' ' + c.fecha + '): ' + c.notas.join(' ')).join(' | '));
  if (!rel) puntos.push('PROVEEDORES: no se consultan (contexto externo apagado).');
  else {
    const reg = rel.argentina_o_region.concat(rel.globales_importantes);
    const desc = rel.otros_paises_descartados + rel.menores_sin_lugar_descartados;
    const nombres = (proveedores.consultados || []).map(corto);
    const quienes = nombres.length > 1 ? nombres.slice(0, -1).join(', ') + ' y ' + nombres[nombres.length - 1] : nombres[0] || 'Los proveedores';
    puntos.push('PROVEEDORES: ' + (reg.length ? reg.map(nov).join(' | ') : quienes + ': sin incidentes ni mantenimientos que afecten a Argentina.') +
      (desc ? ' (' + desc + ' novedades de otros países o menores sin relación: no las menciones).' : '') + (proveedores.errores && proveedores.errores.length ? ' No respondieron: ' + proveedores.errores.join('; ') + '.' : ''));
  }
  const nots = (noticias.noticias || []).slice(0, 5).map((n) => conRef(n, 'N'));
  puntos.push('NOTICIAS (últimas 48 h' + (noticias.fuente ? ', ' + noticias.fuente : '') + ', no verificadas por Helios): ' + (noticias.apagado ? 'no se consultan.' : nots.length ? nots.map((n) => n.titulo + ' (' + n.medio + (n.fecha ? ', ' + n.fecha : '') + ')' + (n.ref ? ' ' + n.ref : '')).join(' | ') + ' — mencioná solo las que puedan afectar pagos, transferencias, recargas o el acceso; si ninguna, decí que no hay noticias relevantes.' : noticias.error ? 'no se pudieron consultar (' + noticias.error + ').' : 'no hay noticias relevantes.'));
  // Qué vigilar: lo arma el servidor cruzando lo de afuera con cómo se ve en Helios (el modelo lo hacía genérico)
  const vig = [];
  if (rel && rel.afectan_a_helios.length) {
    vig.push('Si el tablero, "Revisar alertas ahora" o el asistente dan error o tardan, puede ser el incidente de Cloudflare y no un problema de los clientes.');
    if (rel.afectan_a_helios.some((n) => /workers ai/i.test(n.titulo))) vig.push('El asistente puede fallar o tardar mientras dure el incidente de Workers AI.');
  }
  const notasCal = calendario.slice(0, 2).map((c) => c.notas.join(' ')).join(' ');
  if (/Feriado|Fin de semana largo/.test(notasCal)) vig.push('Feriado o fin de semana largo: se espera menos tráfico; una alerta de volumen bajo puede ser por eso (revisá si el servicio silencia feriados).');
  if (/Primer día hábil después/.test(notasCal)) vig.push('Primer día hábil después del fin de semana largo: es esperable más tráfico de lo normal en transferencias y pagos.');
  if (/día hábil del mes|aguinaldo/.test(notasCal)) vig.push('Cobro de sueldos o aguinaldo: es esperable más tráfico en transferencias, pagos y recargas; una alerta de volumen alto puede ser por eso.');
  for (const e of r[1].results) vig.push(e.nombre + ': ' + (e.efecto_esperado === 'MENOS_TRAFICO' ? 'se espera menos tráfico' : 'se espera más tráfico; una alerta de volumen alto puede ser por eso') + (e.cliente_id ? ' en ' + e.cliente_id : '') + '.');
  if (rel) for (const n of rel.argentina_o_region.concat(rel.globales_importantes).slice(0, 2))
    vig.push(/sms|verif|otp|lookup/i.test(n.titulo) ? 'Si bajan las aprobaciones o suben los rechazos en la app, puede ser que no lleguen los códigos por SMS (' + corto(n.proveedor) + ').' : 'Si aparecen alertas mientras dure "' + (n.titulo_es || n.titulo) + '" de ' + corto(n.proveedor) + ', revisá si coinciden.');
  if (nots.length) vig.push('Si alguna noticia (paro, corte de luz, caída de un banco o billetera) coincide con alertas abiertas, mencionalo al derivar o comentar.');
  puntos.push('QUÉ VIGILAR: ' + (vig.length ? vig.slice(0, 4).join(' | ') : 'Nada fuera de lo común: seguí el monitoreo habitual.'));
  const out = {
    puntos_clave: puntos,
    reloj_helios: asistFecha(ah.ahora) + (ah.simulado ? (usarDemo ? ' (reloj de la demo: el calendario es de esa fecha; proveedores y noticias son de hoy real)' : ' (reloj de la demo; el calendario, los proveedores y las noticias son de la fecha real)') : ''),
    calendario,
    proveedores: rel ? { ...rel, errores: proveedores.errores, actualizado: proveedores.actualizado, error: proveedores.error } : proveedores,
    noticias: { noticias: nots, fuente: noticias.fuente, actualizado: noticias.actualizado, error: noticias.error, apagado: noticias.apagado },
    como_usarlo: 'Respondé solo con puntos_clave, en bloques cortos con estos títulos exactos en negrita: **Helios** (este bloque va únicamente si puntos_clave trae HELIOS MISMO; si no, no lo pongas), **Calendario**, **Proveedores**, **Noticias** y **Qué vigilar** (con lo de QUÉ VIGILAR, sin agregar consejos genéricos). Debajo de cada título, una lista con "- ". Usá los títulos de las novedades tal como vienen (ya están en español). No agregues nada que no esté en puntos_clave ni incidentes de otros países. Para el enlace de cada incidente o noticia escribí solo su código entre corchetes, tal cual, por ejemplo [E1] o [N2]: Helios lo convierte en el enlace. Nunca escribas direcciones web. Si podés, cruzalo con las alertas o servicios del cliente (por ejemplo, SMS de Twilio = códigos de verificación al entrar a la app).',
  };
  if (r[3]) {
    const fmt = (x) => x.cliente_id === '*' ? 'todos los clientes' : x.cliente_id + (x.servicio_id && x.servicio_id !== '*' ? ' / ' + x.servicio_id : '');
    out.servicios_criticos = r[3].results.filter((x) => x.criticidad === 'ALTA').map(fmt);
    out.silencian_feriados = r[3].results.filter((x) => Number(x.silenciar_feriados) === 1).map(fmt);
  }
  out._enlaces = enlaces;   // el asistente los saca antes de mandarle los datos al modelo
  return out;
}

// La herramienta del asistente (todos los perfiles: no muestra datos de clientes salvo a quien ve el tablero)
ASIST_HERRAMIENTAS.contexto_externo = {
  permiso: 'asistente',
  descripcion: 'Lo de afuera que puede afectar la operación hoy y los próximos días: feriados y fines de semana largos, fechas de cobro de sueldos y aguinaldo, eventos comerciales (Black Friday, CyberMonday), incidentes y mantenimientos de proveedores (Cloudflare, Twilio) y noticias de Argentina de las últimas 48 h.',
  parametros: { dias: { type: 'integer', description: 'Cuántos días mirar desde hoy (1 a 7). Por defecto 3' } },
  ejecutar: contextoExterno,
};
ASIST_PALABRAS.unshift([/extern|afuera|noticia|feriado|ma[ñn]ana|pr[oó]xim|semana que viene|fin de semana|proveedor|cloudflare|twilio|paro|huelga|corte|apag[oó]n|evento|hot ?sale|cyber|black friday|cobro|sueldo|aguinaldo|calendario|pueda afectar|puede afectar|afectar/i, 'contexto_externo']);
ASIST_ARGS.contexto_externo = (q) => /semana|7 d[ií]as|pr[oó]ximos d[ií]as/i.test(q) ? { dias: 7 } : /ma[ñn]ana|hoy/i.test(q) ? { dias: 2 } : {};
for (const p of ['SOPORTE', 'ANALISTA', 'GERENTE', 'ADMIN'])
  (ASIST_SUGERENCIAS[p] = ASIST_SUGERENCIAS[p] || []).push({ id: 'contexto', texto: '¿Hay algo de afuera que pueda afectar hoy o mañana?', herramientas: ['contexto_externo'], args: { contexto_externo: { dias: 2 } } });

// ---------- Eventos comerciales (Administración > Umbrales; solo Administrador) ----------
const EFECTOS_EVENTO = ['MAS_TRAFICO', 'MENOS_TRAFICO'];
const ctxFechaOk = (f) => /^\d{4}-\d{2}-\d{2}$/.test(f) && !isNaN(Date.parse(f + 'T12:00:00Z')) && new Date(f + 'T12:00:00Z').toISOString().slice(0, 10) === f;
async function rutasEventos(env, request, p, url, yo) {
  const m = request.method;
  if (m === 'GET' && p === '/eventos') {
    const r = await env.DB.prepare(`SELECT id, nombre, fecha_desde, fecha_hasta, cliente_id, servicio_id, efecto_esperado, nota FROM eventos_comerciales
      WHERE fecha_hasta >= date('now', '-90 days') ORDER BY fecha_desde LIMIT 100`).all();
    return okJson({ eventos: r.results });
  }
  if (m === 'POST' && p === '/eventos') {
    const b = await leerCuerpo(request);
    const nombre = texto(b.nombre, 100), desde = String(b.fecha_desde || ''), hasta = String(b.fecha_hasta || b.fecha_desde || '');
    const cliente = b.cliente_id ? String(b.cliente_id).trim().toUpperCase().slice(0, 40) : null, servicio = b.servicio_id ? String(b.servicio_id).trim().toUpperCase().slice(0, 40) : null;
    const efecto = EFECTOS_EVENTO.includes(b.efecto_esperado) ? b.efecto_esperado : 'MAS_TRAFICO', nota = texto(b.nota, 200) || null;
    if (nombre.length < 3) return jsonError('Poné el nombre del evento.', 400);
    if (!ctxFechaOk(desde) || !ctxFechaOk(hasta)) return jsonError('Fecha inválida.', 400);
    if (hasta < desde) return jsonError('La fecha "hasta" no puede ser anterior a "desde".', 400);
    if ((Date.parse(hasta) - Date.parse(desde)) / 86400000 > 31) return jsonError('Un evento puede durar como máximo un mes.', 400);
    if ((cliente && !/^[A-Z0-9_]+$/.test(cliente)) || (servicio && !/^[A-Z0-9_]+$/.test(servicio))) return jsonError('Cliente y servicio van como en el tablero (por ejemplo CLI_001 y TRANSFERENCIAS).', 400);
    await env.DB.batch([
      env.DB.prepare('INSERT INTO eventos_comerciales (nombre, fecha_desde, fecha_hasta, cliente_id, servicio_id, efecto_esperado, nota, creado_por) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)')
        .bind(nombre, desde, hasta, cliente, servicio, efecto, nota, yo.id),
      env.DB.prepare('INSERT INTO auditoria (usuario_id, accion, detalle) VALUES (?1, ?2, ?3)').bind(yo.id, 'ALTA_EVENTO', nombre + ' (' + desde + ' a ' + hasta + ')'),
    ]);
    return okJson({});
  }
  if (m === 'POST' && p === '/eventos/borrar') {
    const b = await leerCuerpo(request);
    const id = Number(b.id);
    const ev = Number.isInteger(id) ? await env.DB.prepare('SELECT nombre FROM eventos_comerciales WHERE id = ?1').bind(id).first() : null;
    if (!ev) return jsonError('Ese evento no existe.', 404);
    await env.DB.batch([
      env.DB.prepare('DELETE FROM eventos_comerciales WHERE id = ?1').bind(id),
      env.DB.prepare('INSERT INTO auditoria (usuario_id, accion, detalle) VALUES (?1, ?2, ?3)').bind(yo.id, 'BORRAR_EVENTO', ev.nombre),
    ]);
    return okJson({});
  }
  return null;
}

// =====================================================================
// SALA DE CRISIS EN TEAMS (parche 70, etapa 2 del AICIM, partes A y B). Sin SQL nuevo.
//
// A · Avisos en un canal de Teams. Cada novedad de una sala (se abrió, se sumó una alerta, tarea nueva, tarea hecha,
//     escalamiento, cambio de estado, comunicado, cierre) llega al canal como tarjeta, con "Abrir sala en Helios".
//     - El canal se conecta con un flujo de Workflows de Teams ("Publicar en un canal cuando se recibe una solicitud de
//       webhook"). La dirección que da el flujo se carga como secreto del Worker: TEAMS_WEBHOOK.
//     - Sin el secreto no hace nada ni consulta la base.
//     - Sale de incidente_linea_tiempo: antes del pedido se toma el último id y después se mandan los renglones nuevos.
//       No se mandan las notas ni "empezó la tarea" (para no llenar el canal).
//     - Costo: solo en los POST de la sala y de "Comunicar incidente", y solo con el secreto: 2 consultas y 1 pedido a Teams.
//     - Solo se aceptan direcciones de Microsoft (Workflows / Power Automate / Logic Apps).
//     - Si Teams falla, la acción en Helios igual se hace (queda en el registro: "Teams: …").
//
// B · "Chat en Teams" en la sala: abre un chat grupal de Teams (enlace teams.microsoft.com/l/chat) con quienes están en
//     la sala (quien la abrió, quien la dirige, responsables de tareas y la gente de Soporte de los equipos con tareas),
//     con el título del incidente y el enlace a la sala. Usa usuarios.correo (script 23). No necesita Azure.
// =====================================================================
const TEAMS_HOSTS = /^https:\/\/[a-z0-9.-]+\.(logic\.azure\.com|powerplatform\.com|powerautomate\.com|azure-apim\.net|webhook\.office\.com)(:443)?\//i;
const TEAMS_TOPE_MS = 5000;
const TEAMS_MAX_RENGLONES = 8;
const TEAMS_MAX_CHAT = 40;   // personas en el enlace del chat (el enlace tiene que entrar en una URL)
const TEAMS_RUTAS = /^\/api\/(incidentes(\/|$)|alertas\/[^/]+\/(comunicar|derivar|tomar|devolver|resolver)$)/;
const TEAMS_SEV = { CRITICA: 'Grave', ALTA: 'Importante' };

function teamsUrl(env) {
  const u = String((env && env.TEAMS_WEBHOOK) || '').trim();
  return u && u.length < 2000 && !/\s/.test(u) && TEAMS_HOSTS.test(u) ? u : null;
}

// Antes del pedido: hasta qué renglón de la línea de tiempo ya se conocía (null = no hace falta mandar nada)
async function teamsMarca(env, request, ruta) {
  if (request.method !== 'POST' || !TEAMS_RUTAS.test(ruta) || !teamsUrl(env) || !env.DB) return null;
  try { const r = await env.DB.prepare('SELECT COALESCE(MAX(id), 0) AS m FROM incidente_linea_tiempo').first(); return r ? r.m : null; }
  catch (e) { return null; }   // sin el script 24
}

// Un renglón de la línea de tiempo merece ir al canal?
function teamsVaAlCanal(x) {
  if (x.tipo === 'NOTA') return false;
  if (x.tipo === 'TAREA') return /^Asignó la tarea|: hecha/.test(x.texto || '');
  return true;
}

function teamsTarjetaSala(inc, renglones, resto, origen) {
  const urgente = inc.estado === 'ABIERTO' && inc.severidad === 'CRITICA';
  const est = { ABIERTO: 'Abierto', MITIGADO: 'Mitigado', RESUELTO: 'Resuelto', CERRADO: 'Cerrado' }[inc.estado] || inc.estado;
  const cuerpo = [
    { type: 'TextBlock', text: 'Helios · Sala de crisis', size: 'Small', isSubtle: true, spacing: 'None' },
    { type: 'TextBlock', text: (urgente ? '🔴 ' : '') + 'IM-' + inc.id + ' · ' + inc.titulo, weight: 'Bolder', size: 'Medium', wrap: true, color: urgente ? 'Attention' : 'Default', spacing: 'None' },
    { type: 'TextBlock', text: [est, TEAMS_SEV[inc.severidad], inc.cliente_id, inc.servicio_id ? (PUSH_SERVICIO[inc.servicio_id] || inc.servicio_id) : null].filter(Boolean).join(' · '), isSubtle: true, wrap: true, spacing: 'None' },
  ];
  for (const x of renglones) {
    cuerpo.push({ type: 'TextBlock', text: '**' + (x.usuario || 'Helios') + '**: ' + x.texto, wrap: true, separator: true, spacing: 'Small' });
  }
  if (resto > 0) cuerpo.push({ type: 'TextBlock', text: 'Y ' + resto + ' novedades más en la sala.', isSubtle: true, size: 'Small' });
  const tarjeta = { $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4', body: cuerpo };
  if (/^https:\/\//.test(origen || '')) tarjeta.actions = [{ type: 'Action.OpenUrl', title: 'Abrir sala en Helios', url: origen + '/incidente/' + inc.id }];
  return { type: 'message', attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', contentUrl: null, content: tarjeta }] };
}

// Aviso de prueba (parche 73): tarjeta propia, sin número de sala ni estado
function teamsTarjetaPrueba(nombre, origen) {
  const tarjeta = { $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4', body: [
    { type: 'TextBlock', text: 'Helios · Monitoreo', size: 'Small', isSubtle: true, spacing: 'None' },
    { type: 'TextBlock', text: 'Aviso de prueba', weight: 'Bolder', size: 'Medium', wrap: true, spacing: 'None' },
    { type: 'TextBlock', text: 'Lo mandó **' + nombre + '** desde Administración. El canal quedó conectado: acá van a llegar las novedades de las salas de crisis.', wrap: true, spacing: 'Small' },
  ] };
  if (/^https:\/\//.test(origen || '')) tarjeta.actions = [{ type: 'Action.OpenUrl', title: 'Abrir Helios', url: origen + '/inicio' }];
  return { type: 'message', attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', contentUrl: null, content: tarjeta }] };
}

async function teamsMandar(url, mensaje) {
  const r = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(mensaje), signal: AbortSignal.timeout(TEAMS_TOPE_MS) });
  if (!r.ok) throw new Error('Teams respondió ' + r.status + ': ' + (await r.text()).slice(0, 200));
  return r.status;
}

// Después del pedido: una tarjeta por sala con sus novedades
async function enviarTeamsSala(env, desde, origen) {
  const url = teamsUrl(env);
  if (!url || desde == null) return { enviados: 0 };
  const filas = (await env.DB.prepare(`SELECT l.id, l.incidente_id, l.tipo, l.texto, u.nombre AS usuario,
      i.titulo, i.estado, i.severidad, i.cliente_id, i.servicio_id
    FROM incidente_linea_tiempo l JOIN incidentes_mayores i ON i.id = l.incidente_id LEFT JOIN usuarios u ON u.id = l.usuario_id
    WHERE l.id > ?1 AND i.origen = 'HELIOS' ORDER BY l.id LIMIT 60`).bind(desde).all()).results.filter(teamsVaAlCanal);
  const porSala = new Map();
  for (const x of filas) { if (!porSala.has(x.incidente_id)) porSala.set(x.incidente_id, []); porSala.get(x.incidente_id).push(x); }
  let enviados = 0;
  for (const [id, rs] of porSala) {
    const inc = { id, titulo: rs[0].titulo, estado: rs[0].estado, severidad: rs[0].severidad, cliente_id: rs[0].cliente_id, servicio_id: rs[0].servicio_id };
    await teamsMandar(url, teamsTarjetaSala(inc, rs.slice(0, TEAMS_MAX_RENGLONES), rs.length - TEAMS_MAX_RENGLONES, origen));
    enviados++;
  }
  return { enviados };
}

// ---------- B · Chat en Teams ----------
// Quiénes están en la sala, con su correo. Quien mira no va en la lista (Teams lo suma solo).
async function teamsChatSala(env, yo, inc, tareas) {
  if (!(await hayCorreoUsuarios(env))) return { correos: [], sin_correo: [], falta_script: true };
  const ids = new Set([inc.abierto_por, inc.responsable_usuario_id]);
  const equipos = new Set();
  for (const t of tareas) {
    if (t.estado === 'CANCELADA') continue;
    if (t.responsable_usuario_id != null) ids.add(t.responsable_usuario_id);
    else if (t.equipo_id != null) equipos.add(t.equipo_id);
  }
  for (const e of equipos) for (const u of await miembrosActivos(env, e)) ids.add(u);
  ids.delete(null); ids.delete(undefined); ids.delete(yo.id);
  if (!ids.size) return { correos: [], sin_correo: [] };
  const lista = [...ids].slice(0, 90);
  const r = await env.DB.prepare(`SELECT id, nombre, correo FROM usuarios WHERE activo = 1 AND id IN (${lista.map((_, i) => '?' + (i + 1)).join(', ')}) ORDER BY nombre COLLATE NOCASE`)
    .bind(...lista).all();
  const con = r.results.filter((u) => u.correo), sin = r.results.filter((u) => !u.correo);
  return { correos: con.slice(0, TEAMS_MAX_CHAT).map((u) => u.correo), nombres: con.slice(0, TEAMS_MAX_CHAT).map((u) => u.nombre), sin_correo: sin.map((u) => u.nombre) };
}

// ---------- Administración > Equipos: estado y aviso de prueba (solo Administrador) ----------
async function rutasTeams(env, request, p, yo) {
  if (request.method === 'GET' && p === '/teams') {
    return okJson({ configurado: !!teamsUrl(env), cargado: !!(env && env.TEAMS_WEBHOOK) });
  }
  if (request.method === 'POST' && p === '/teams/probar') {
    const url = teamsUrl(env);
    if (!url) return jsonError(env && env.TEAMS_WEBHOOK ? 'La dirección cargada en TEAMS_WEBHOOK no es de un flujo de Workflows de Teams.' : 'Falta cargar el secreto TEAMS_WEBHOOK en el Worker.', 409);
    const msg = teamsTarjetaPrueba(yo.nombre, new URL(request.url).origin);
    try { await teamsMandar(url, msg); }
    catch (e) { return jsonError('No se pudo mandar a Teams (' + (e.name === 'TimeoutError' ? 'no respondió a tiempo' : e.message) + ').', 502); }
    await env.DB.prepare('INSERT INTO auditoria (usuario_id, accion, detalle) VALUES (?1, ?2, ?3)').bind(yo.id, 'TEAMS_PRUEBA', 'Aviso de prueba a Teams').run();
    return okJson({});
  }
  return null;
}

// =====================================================================
// BOT DE HELIOS EN TEAMS (parche 76, parte C de la sala de crisis en Teams). Sin SQL nuevo.
//
// El asistente de IA de Helios como bot de Microsoft Teams: se le escribe en el chat de la sala (o en un chat de a dos) y responde
// con lo que la persona puede ver en Helios, con los datos de la sala (alertas, tareas, guía de diagnóstico, casos parecidos, contexto
// externo). Solo lee y propone: nada se ejecuta desde Teams; las propuestas se confirman en Helios (se manda el enlace).
//
//   POST /api/teams/bot                 lo llama Microsoft (Bot Framework) con cada mensaje. Sin sesión: se valida la firma.
//   GET  /api/admin/teams/bot           estado (qué falta cargar) y dirección de mensajes (Administrador)
//   POST /api/admin/teams/bot/probar    pide un token a Microsoft con el App ID y el secreto cargados (Administrador)
//
// Secretos del Worker (los entrega IT al registrar el bot en el Developer Portal de Teams o en Azure Bot):
//   TEAMS_BOT_APP_ID   el Bot ID / Microsoft App ID (un GUID)
//   TEAMS_BOT_SECRET   el secreto de cliente
//   TEAMS_BOT_TENANT   el ID del tenant (obligatorio si el bot es de un solo tenant; si es multi-tenant se deja vacío)
//   TEAMS_BOT_NOMBRE   (opcional) el nombre con el que se lo menciona en Teams; por defecto Gemma (el que figure como nombre de la app)
// Sin App ID y secreto el bot no hace nada (responde 503 a Microsoft) y el resto de Helios anda igual.
//
// Seguridad:
//   - Cada pedido trae un token de Microsoft: se verifica la firma RS256 con las claves públicas de Bot Framework (o del tenant),
//     que el destinatario sea este bot, que no esté vencido y que la dirección del servicio sea la del mensaje. Si falla: 401.
//   - Las respuestas solo se mandan a direcciones de servicio de Microsoft (smba.trafficmanager.net y *.botframework.com).
//   - Quién pregunta se identifica por su correo de Teams, que se busca en usuarios.correo (script 23). Sin usuario no hay datos.
//     La pregunta pasa por la misma ruta del asistente de siempre (/api/asistente): mismos permisos por perfil, mismos límites
//     de preguntas por hora y por día, misma auditoría, y las mismas reglas de la sala (Soporte solo ve salas donde tiene una tarea).
//   - Los saludos y agradecimientos sueltos no llaman al modelo (parche 74).
//   - Recuerda la conversación (parches 77 y 78, script 25): últimos 6 mensajes de cada chat (con el nombre de quien preguntó) y la sala de la que venían hablando;
//     es del chat, no de cada persona, porque en un chat grupal todos leen las mismas respuestas. «Empezar de nuevo» la borra.
//   - El pedido se contesta enseguida (200) y la respuesta se manda después, por la API de Microsoft: la IA puede tardar unos segundos.
// =====================================================================
const BOT_RUTA = '/api/teams/bot';
const BOT_GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const BOT_SERVICIOS = /^https:\/\/(smba\.trafficmanager\.net|([a-z0-9-]+\.)+botframework\.com|smba\.infra\.[a-z0-9.-]+\.microsoft\.(com|us))\//i;
const BOT_JWKS_BF = 'https://login.botframework.com/v1/.well-known/keys';
const BOT_TOPE_MS = 8000;
const BOT_MAX_CUERPO = 100000;
const BOT_MAX_RESPUESTA = 3800;
// El nombre con el que se lo menciona en Teams (@Gemma) es el de la app: lo manda Teams en cada mensaje (act.recipient.name) y, si no, TEAMS_BOT_NOMBRE
const BOT_NOMBRE_FABRICA = 'Gemma';
function botNombre(env, act) {
  const n = String((act && act.recipient && act.recipient.name) || (env && env.TEAMS_BOT_NOMBRE) || BOT_NOMBRE_FABRICA).replace(/[<>@]/g, '').trim().slice(0, 30);
  return n || BOT_NOMBRE_FABRICA;
}
function botSinNombre(texto, nombre) {   // «gemma, ¿qué reviso?» → «¿qué reviso?»
  const t = String(texto).replace(/^@/, ''), n = nombre.toLowerCase();
  if (t.toLowerCase().startsWith(n) && !/[\p{L}\p{N}_]/u.test(t.charAt(n.length) || ' ')) return t.slice(n.length).replace(/^[\s,:;-]+/, '').trim();
  return texto;
}
const botSaludo = (nombre) => 'Hola, soy ' + nombre + ', el asistente de Helios. Mencioname y preguntame por la operación; por ejemplo: **@' + nombre + ' IM-4 ¿qué reviso primero?**, **¿qué alertas tengo asignadas?**, '
  + '**¿qué tareas tengo en las salas?** o **¿hubo algo parecido antes?** '
  + 'Respondo con lo que tu perfil puede ver en Helios. No hago cambios: si propongo algo, lo confirmás en Helios.';
let BOT_JWKS = {};          // dirección de las claves -> { t, claves }
let BOT_TOKEN = null;       // { valor, vence }
const BOT_CORREOS = new Map();   // id de Teams -> { t, correos }

function botConfig(env) {
  const id = String((env && env.TEAMS_BOT_APP_ID) || '').trim(), secreto = String((env && env.TEAMS_BOT_SECRET) || '').trim(), tenant = String((env && env.TEAMS_BOT_TENANT) || '').trim();
  return { id: BOT_GUID.test(id) ? id.toLowerCase() : null, secreto: secreto.length >= 8 && secreto.length < 400 ? secreto : null, tenant: BOT_GUID.test(tenant) ? tenant.toLowerCase() : null,
    cargado: !!(id || secreto || tenant) };
}

// ---------- Token que manda Microsoft ----------
function botBytes(s) {
  const t = String(s).replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(t + '='.repeat((4 - (t.length % 4)) % 4));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}
const botTexto = (s) => new TextDecoder().decode(botBytes(s));
async function botJwks(url, forzar) {
  const c = BOT_JWKS[url];
  if (c && Date.now() - c.t < (forzar ? 300e3 : 3600e3)) return c.claves;   // se vuelve a pedir como mucho cada 5 minutos si aparece una clave nueva
  const r = await fetch(url, { signal: AbortSignal.timeout(BOT_TOPE_MS) });
  if (!r.ok) throw new Error('no se pudieron leer las claves de Microsoft (' + r.status + ')');
  const claves = ((await r.json()).keys) || [];
  BOT_JWKS[url] = { t: Date.now(), claves };
  return claves;
}
// Devuelve null si el pedido es de Microsoft y para este bot; si no, el motivo (solo para el registro, no se le muestra a nadie)
async function botValidar(env, request, act) {
  const cfg = botConfig(env);
  const m = (request.headers.get('authorization') || '').match(/^Bearer\s+([A-Za-z0-9._-]+)$/);
  if (!m) return 'falta el token';
  const partes = m[1].split('.');
  if (partes.length !== 3) return 'token mal formado';
  let cab, carga;
  try { cab = JSON.parse(botTexto(partes[0])); carga = JSON.parse(botTexto(partes[1])); } catch (e) { return 'token mal formado'; }
  if (!cab || !carga || cab.alg !== 'RS256' || !cab.kid) return 'algoritmo no aceptado';
  const iss = String(carga.iss || '');
  const deBotFramework = iss === 'https://api.botframework.com';
  const deTenant = !!cfg.tenant && (iss === 'https://sts.windows.net/' + cfg.tenant + '/' || iss === 'https://login.microsoftonline.com/' + cfg.tenant + '/v2.0');
  if (!deBotFramework && !deTenant) return 'emisor no aceptado: ' + iss.slice(0, 80);
  if (String(carga.aud || '').toLowerCase() !== cfg.id) return 'el token no es para este bot';
  const ahora = Math.floor(Date.now() / 1000);
  if (!Number.isFinite(carga.exp) || carga.exp < ahora - 300) return 'token vencido';
  if (Number.isFinite(carga.nbf) && carga.nbf > ahora + 300) return 'token todavía no vale';
  if (deBotFramework) {
    const su = String(carga.serviceurl || carga.serviceUrl || '').replace(/\/+$/, '').toLowerCase();
    if (!su || su !== String(act.serviceUrl || '').replace(/\/+$/, '').toLowerCase()) return 'la dirección del servicio no coincide con la del token';
  }
  const url = deBotFramework ? BOT_JWKS_BF : 'https://login.microsoftonline.com/' + cfg.tenant + '/discovery/v2.0/keys';
  let clave = (await botJwks(url, false)).find((x) => x.kid === cab.kid);
  if (!clave) clave = (await botJwks(url, true)).find((x) => x.kid === cab.kid);
  if (!clave || clave.kty !== 'RSA') return 'clave desconocida';
  if (deBotFramework && Array.isArray(clave.endorsements) && act.channelId && !clave.endorsements.includes(act.channelId)) return 'clave no habilitada para el canal';
  const llave = await crypto.subtle.importKey('jwk', { kty: 'RSA', n: clave.n, e: clave.e, alg: 'RS256', ext: true }, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['verify']);
  const firmado = await crypto.subtle.verify('RSASSA-PKCS1-v1_5', llave, botBytes(partes[2]), new TextEncoder().encode(partes[0] + '.' + partes[1]));
  return firmado ? null : 'firma inválida';
}

// ---------- Hablar con Microsoft ----------
async function botToken(env, forzar) {
  const cfg = botConfig(env);
  if (!cfg.id || !cfg.secreto) throw new Error('el bot no está configurado');
  if (!forzar && BOT_TOKEN && BOT_TOKEN.vence > Date.now() + 60e3) return BOT_TOKEN.valor;
  const r = await fetch('https://login.microsoftonline.com/' + (cfg.tenant || 'botframework.com') + '/oauth2/v2.0/token', {
    method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, signal: AbortSignal.timeout(BOT_TOPE_MS),
    body: new URLSearchParams({ grant_type: 'client_credentials', client_id: cfg.id, client_secret: cfg.secreto, scope: 'https://api.botframework.com/.default' }).toString(),
  });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || !j.access_token) throw new Error('Microsoft no dio el token (' + r.status + (j.error_description ? ': ' + String(j.error_description).split('\n')[0].slice(0, 160) : '') + ')');
  BOT_TOKEN = { valor: j.access_token, vence: Date.now() + (Number(j.expires_in) || 3600) * 1000 };
  return BOT_TOKEN.valor;
}
async function botLlamar(env, metodo, url, cuerpo, reintento) {
  const token = await botToken(env, !!reintento);
  const r = await fetch(url, { method: metodo, headers: { authorization: 'Bearer ' + token, 'content-type': 'application/json' },
    body: cuerpo === undefined ? undefined : JSON.stringify(cuerpo), signal: AbortSignal.timeout(BOT_TOPE_MS) });
  if (r.status === 401 && !reintento) return await botLlamar(env, metodo, url, cuerpo, true);   // el token pudo haber vencido: se pide uno nuevo una vez
  if (!r.ok) throw new Error('Teams respondió ' + r.status + ': ' + (await r.text().catch(() => '')).slice(0, 200));
  return r;
}
const botBase = (act) => String(act.serviceUrl).replace(/\/+$/, '') + '/v3/conversations/' + encodeURIComponent(act.conversation.id);
async function botResponder(env, act, texto) {
  await botLlamar(env, 'POST', botBase(act) + '/activities' + (act.id ? '/' + encodeURIComponent(act.id) : ''), {
    type: 'message', text: String(texto).slice(0, BOT_MAX_RESPUESTA), textFormat: 'markdown',
    from: act.recipient, conversation: { id: act.conversation.id }, recipient: act.from, replyToId: act.id,
  });
}
async function botEscribiendo(env, act) {   // "Helios está escribiendo…" mientras piensa (si falla, no pasa nada)
  try { await botLlamar(env, 'POST', botBase(act) + '/activities', { type: 'typing', from: act.recipient, conversation: { id: act.conversation.id }, recipient: act.from }); }
  catch (e) { /* es solo un detalle de la pantalla */ }
}

// ---------- Quién pregunta ----------
async function botCorreos(env, act) {
  const id = act.from && act.from.id;
  if (!id) return [];
  const c = BOT_CORREOS.get(id);
  if (c && Date.now() - c.t < 3600e3) return c.correos;
  const j = await (await botLlamar(env, 'GET', botBase(act) + '/members/' + encodeURIComponent(id))).json().catch(() => ({}));
  const correos = [...new Set([j.email, j.userPrincipalName].filter(Boolean).map((x) => String(x).trim().toLowerCase()))];
  if (BOT_CORREOS.size > 500) BOT_CORREOS.clear();
  BOT_CORREOS.set(id, { t: Date.now(), correos });
  return correos;
}
async function botUsuario(env, correos) {
  if (!correos.length) return null;
  const a = correos[0], b = correos[1] || correos[0];
  return await conPerfil(
    () => env.DB.prepare(`SELECT id, usuario, nombre, CASE WHEN solo_comunicados = 1 THEN 'COMUNICADOS' ELSE perfil END AS perfil, debe_cambiar
      FROM usuarios WHERE activo = 1 AND lower(correo) IN (?1, ?2) ORDER BY id LIMIT 1`).bind(a, b).first(),
    () => env.DB.prepare('SELECT id, usuario, nombre, perfil, debe_cambiar FROM usuarios WHERE activo = 1 AND lower(correo) IN (?1, ?2) ORDER BY id LIMIT 1').bind(a, b).first());
}

// ---------- Memoria de la conversación (parches 77 y 78, script 25) ----------
// Una fila por CHAT con sus últimos mensajes (hasta 6, con el nombre de quien preguntó cada uno) y la sala de la que venían hablando. Es del chat y no
// de cada persona: en un chat grupal todos leen las mismas respuestas, así que si alguien pregunta y otra persona sigue después, el bot responde en
// base a lo que se viene hablando ahí. El permiso de cada pregunta sigue siendo el de quien la hace. Se usa hasta 2 horas después del último
// mensaje y lo viejo (más de 7 días) se borra solo. Sin la tabla, cada mensaje es independiente.
const BOT_MEMORIA_MENSAJES = 6;
const BOT_MEMORIA_HORAS = 2;
const BOT_OLVIDAR = /^(empezar de nuevo|empecemos de nuevo|nueva consulta|nueva conversaci[oó]n|olvid[aá](te)?( todo| lo anterior)?|reiniciar|borr[aá] (la )?(memoria|conversaci[oó]n))[.!? ]*$/i;
const botChat = (act) => String(act.conversation.id).slice(0, 200);
async function botMemoria(env, act) {
  try {
    const f = await env.DB.prepare('SELECT mensajes, sala_id, actualizado FROM teams_bot_memoria WHERE conversacion_id = ?1').bind(botChat(act)).first();
    if (!f || Date.parse(f.actualizado) < Date.now() - BOT_MEMORIA_HORAS * 3600e3) return { mensajes: [], sala_id: null, activa: true };
    let ms = []; try { ms = JSON.parse(f.mensajes); } catch (e) { /* fila ilegible: se empieza de nuevo */ }
    return { mensajes: Array.isArray(ms) ? ms.filter((x) => x && (x.rol === 'usuario' || x.rol === 'asistente') && typeof x.texto === 'string').slice(-BOT_MEMORIA_MENSAJES) : [], sala_id: f.sala_id, activa: true };
  } catch (e) {
    if (/no such table|no such column/i.test(e.message)) return { mensajes: [], sala_id: null, activa: false };   // sin el script 25
    throw e;
  }
}
// Lo que se le pasa al modelo: cada pregunta con el nombre de quien la hizo, para que distinga quién dijo qué
const botHistoria = (mensajes) => mensajes.map((m) => ({ rol: m.rol, texto: m.rol === 'usuario' && m.quien ? m.quien + ': ' + m.texto : m.texto }));
async function botGuardarMemoria(env, act, mensajes, salaId) {
  try {
    await env.DB.batch([
      env.DB.prepare(`INSERT INTO teams_bot_memoria (conversacion_id, mensajes, sala_id, actualizado) VALUES (?1, ?2, ?3, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
        ON CONFLICT (conversacion_id) DO UPDATE SET mensajes = excluded.mensajes, sala_id = excluded.sala_id, actualizado = excluded.actualizado`)
        .bind(botChat(act), JSON.stringify(mensajes.slice(-BOT_MEMORIA_MENSAJES)), salaId || null),
      env.DB.prepare("DELETE FROM teams_bot_memoria WHERE actualizado < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-7 days')"),
    ]);
  } catch (e) { if (!/no such table|no such column/i.test(e.message)) console.error('Bot de Teams: no se pudo guardar la memoria: ' + e.message); }
}
// Al instalar la app, Teams manda dos avisos (installationUpdate y conversationUpdate) y cada uno saludaba: el chat recibía el saludo dos veces (parche 79).
// Ahora saluda uno solo por chat: el primero que llega anota una marca en la misma tabla de memoria (clave «saludo:<chat>», atómico) y el otro la encuentra.
// Si se lo saca y se lo vuelve a sumar pasados 10 minutos, saluda de nuevo. Sin el script 25 no hay dónde anotar: saluda solo con conversationUpdate.
async function botSaludar(env, act, evento) {
  let saluda = true;
  try {
    const r = await env.DB.prepare(`INSERT INTO teams_bot_memoria (conversacion_id, mensajes, sala_id, actualizado) VALUES (?1, '[]', NULL, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      ON CONFLICT (conversacion_id) DO UPDATE SET actualizado = excluded.actualizado WHERE teams_bot_memoria.actualizado < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-10 minutes')`)
      .bind('saludo:' + botChat(act)).run();
    saluda = !!(r.meta && r.meta.changes > 0);
  } catch (e) {
    if (!/no such table|no such column/i.test(e.message)) console.error('Bot de Teams: no se pudo anotar el saludo: ' + e.message);
    saluda = evento === 'conversationUpdate';
  }
  if (saluda) await botResponder(env, act, botSaludo(botNombre(env, act)));
}
async function botOlvidar(env, act) {
  try { await env.DB.prepare('DELETE FROM teams_bot_memoria WHERE conversacion_id = ?1').bind(botChat(act)).run(); }
  catch (e) { if (!/no such table|no such column/i.test(e.message)) throw e; }
}

// ---------- Sobre qué sala pregunta ----------
// 1) lo que escribe ("IM-4"): si no existe o no la ve, se le dice. Si no lo escribe, se prueba (2) el título del chat de Helios ("IM-4 · …"), (3) la sala de la que
// venía hablando y (4) la única sala abierta, pero SOLO si existe y la persona la puede ver (parche 79): si no, la pregunta sigue como una pregunta general
// (sus alertas, sus tareas, casos parecidos). Antes, una sala que ya no existía (por ejemplo, después de «Preparar demo») o una sala donde la persona no tiene
// tareas hacía que el bot contestara «Ese incidente no existe.» o «Esa sala de crisis no tiene tareas…» aunque preguntara por lo suyo.
async function botSalaVisible(env, yo, id) {
  try { return !(await rolEnIncidente(env, yo, id)).error; }
  catch (e) { return false; }   // sin el script 24
}
async function botSala(env, yo, texto, act, memoria) {
  const m = texto.match(/\bIM-(\d{1,6})\b/i);
  if (m) return { id: Number(m[1]) };
  const t = String((act.conversation && act.conversation.name) || '').match(/\bIM-(\d{1,6})\b/i);
  for (const id of [t && Number(t[1]), memoria && memoria.mensajes.length && memoria.sala_id].filter(Boolean)) if (await botSalaVisible(env, yo, id)) return { id };
  if (!puede(yo, 'sala_crisis')) return {};
  try {
    const r = (await env.DB.prepare("SELECT id FROM incidentes_mayores WHERE estado <> 'CERRADO' ORDER BY id DESC LIMIT 3").all()).results;
    const vistas = [];
    for (const x of r) if (await botSalaVisible(env, yo, x.id)) vistas.push(x.id);
    if (vistas.length === 1) return { id: vistas[0] };
    if (vistas.length > 1) return { varias: true };
  } catch (e) { /* sin el script 24 */ }
  return {};
}

const botLimpiar = (t) => String(t || '').replace(/<at>.*?<\/at>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim().slice(0, 600);

function botArmarRespuesta(j, origen, sala) {
  let t = String(j.respuesta || '').trim() || 'No pude armar una respuesta. Probá preguntarlo de otra forma.';
  const acc = Array.isArray(j.acciones) ? j.acciones : [];
  if (acc.length) {
    t += '\n\n**Propuestas (no se hizo nada)**\n' + acc.map((a) => '- ' + [String(a.titulo || a.tipo || 'Acción') + (a.destino ? ' → ' + a.destino : ''), a.alerta, a.motivo].filter(Boolean).join(' · ')).join('\n');
    const donde = sala.id ? origen + '/incidente/' + sala.id : acc[0].alerta_id ? origen + '/alerta/' + acc[0].alerta_id : origen + '/inicio';
    t += '\n\nPara hacerlo, abrilo en Helios: ' + donde;
  } else if (sala.id) {
    t += '\n\n[Abrir la sala IM-' + sala.id + ' en Helios](' + origen + '/incidente/' + sala.id + ')';
  }
  if (sala.varias && !sala.id) t += '\n\n_Hay varias salas abiertas: para preguntar por una, escribí su número, por ejemplo IM-4._';
  return t.slice(0, BOT_MAX_RESPUESTA);
}

// ---------- Un mensaje de Teams ----------
async function botProcesar(env, request, act) {
  const origen = new URL(request.url).origin;
  const tipo = String(act.type || '');
  if (tipo === 'conversationUpdate') {
    if ((act.membersAdded || []).some((x) => x && act.recipient && x.id === act.recipient.id)) await botSaludar(env, act, 'conversationUpdate');
    return;
  }
  if (tipo === 'installationUpdate') { if (act.action === 'add') await botSaludar(env, act, 'installationUpdate'); return; }
  if (tipo !== 'message') return;
  // Además de la mención de Teams, en un chat de a dos se lo puede llamar por el nombre («gemma, ¿qué reviso?»)
  const nombre = botNombre(env, act);
  const texto = botSinNombre(botLimpiar(act.text), nombre);
  if (!texto) { await botResponder(env, act, botSaludo(nombre)); return; }
  let correos;
  try { correos = await botCorreos(env, act); }
  catch (e) { console.error('Bot de Teams: no se pudo leer quién escribe: ' + e.message); await botResponder(env, act, 'No pude confirmar quién sos en Teams. Probá de nuevo en un momento.'); return; }
  let yo;
  try { yo = await botUsuario(env, correos); }
  catch (e) { console.error('Bot de Teams: ' + e.message); await botResponder(env, act, 'Todavía falta configurar el correo de los usuarios en Helios (script 23). Avisale al Administrador.'); return; }
  if (!yo) { await botResponder(env, act, 'No encontré tu usuario de Helios' + (correos[0] ? ' con el correo ' + correos[0] : '') + '. Pedile al Administrador que cargue tu correo en Administración > Usuarios.'); return; }
  if (!puede(yo, 'asistente')) { await botResponder(env, act, 'Tu perfil no tiene el asistente.'); return; }
  if (BOT_OLVIDAR.test(texto)) {
    await botOlvidar(env, act);
    await botResponder(env, act, 'Listo, empezamos de nuevo: no recuerdo lo anterior de este chat. Preguntame lo que necesites.');
    return;
  }
  await botEscribiendo(env, act);
  let memoria = await botMemoria(env, act);
  const sala = await botSala(env, yo, texto, act, memoria);
  // Si ahora se pregunta por otra sala, lo anterior era de otro tema: se empieza de nuevo
  // Otra sala escrita a mano: lo anterior era de otro tema. Si la sala de la que venía hablando el chat existe pero esta persona no la ve, contesta como pregunta general
  // (sin la conversación del chat y sin tocarla: no se guarda), y si ya no existe (por ejemplo, después de «Preparar demo») se empieza de nuevo.
  let aparte = false;
  if (memoria.sala_id && sala.id !== memoria.sala_id) {
    if (!sala.id) { try { aparte = !!(await env.DB.prepare('SELECT 1 FROM incidentes_mayores WHERE id = ?1').bind(memoria.sala_id).first()); } catch (e) { /* sin el script 24 */ } }
    memoria = { ...memoria, mensajes: [] };
  }
  const cuerpo = { pregunta: texto };
  if (sala.id) cuerpo.incidente_id = sala.id;
  if (memoria.mensajes.length) cuerpo.historia = botHistoria(memoria.mensajes);
  // La misma ruta del asistente de siempre: permisos del perfil, límites de preguntas, auditoría y reglas de la sala
  const resp = await rutasAsistente(env, new Request(origen + '/api/asistente', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(cuerpo) }), '/api/asistente', yo);
  const j = await resp.json().catch(() => ({}));
  if (!resp.ok || j.ok === false) { await botResponder(env, act, String(j.error || 'No pude responder ahora. Probá de nuevo en un momento.')); return; }
  await botResponder(env, act, botArmarRespuesta(j, origen, sala));
  // Se recuerda lo conversado (sin los saludos sueltos, que no pasaron por el modelo)
  if (memoria.activa && !aparte && !j.sin_ia && j.respuesta) await botGuardarMemoria(env, act, memoria.mensajes.concat([{ rol: 'usuario', texto, quien: String(yo.nombre || '').split(/\s+/)[0] }, { rol: 'asistente', texto: String(j.respuesta).slice(0, 1500) }]), sala.id);
}

// ---------- Lo que llama Microsoft ----------
async function botTeamsRuta(env, request, ctx) {
  const cfg = botConfig(env);
  if (!cfg.id || !cfg.secreto) return Response.json({ ok: false, error: 'El bot de Teams no está configurado.' }, { status: 503 });
  let act;
  try {
    if (Number(request.headers.get('content-length') || 0) > BOT_MAX_CUERPO) return Response.json({ ok: false }, { status: 413 });
    const t = await request.text();
    if (t.length > BOT_MAX_CUERPO) return Response.json({ ok: false }, { status: 413 });
    act = JSON.parse(t);
  } catch (e) { return Response.json({ ok: false }, { status: 400 }); }
  if (!act || typeof act !== 'object' || !act.serviceUrl || !act.conversation || !act.conversation.id || !BOT_SERVICIOS.test(String(act.serviceUrl).replace(/\/*$/, '/'))) {
    return Response.json({ ok: false }, { status: 400 });
  }
  const motivo = await botValidar(env, request, act).catch((e) => 'error: ' + e.message);
  if (motivo) { console.error('Bot de Teams: pedido rechazado (' + motivo + ')'); return Response.json({ ok: false, error: 'No autorizado.' }, { status: 401 }); }
  const tid = act.channelData && act.channelData.tenant && act.channelData.tenant.id;
  if (cfg.tenant && tid && String(tid).toLowerCase() !== cfg.tenant) return new Response(null, { status: 200 });   // de otro tenant: se ignora
  const tarea = botProcesar(env, request, act).catch((e) => console.error('Bot de Teams: ' + e.message));
  if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(tarea); else await tarea;
  return new Response(null, { status: 200 });
}

// ---------- Administración > Equipos: estado y prueba de conexión (solo Administrador) ----------
async function rutasTeamsBot(env, request, p, yo) {
  const cfg = botConfig(env);
  if (request.method === 'GET' && p === '/teams/bot') {
    const falta = [];
    if (!cfg.id) falta.push('TEAMS_BOT_APP_ID');
    if (!cfg.secreto) falta.push('TEAMS_BOT_SECRET');
    let memoria = true;
    try { await env.DB.prepare('SELECT 1 FROM teams_bot_memoria LIMIT 1').all(); } catch (e) { if (/no such table/i.test(e.message)) memoria = false; else throw e; }
    return okJson({ configurado: !!(cfg.id && cfg.secreto), falta, con_tenant: !!cfg.tenant, algo_cargado: cfg.cargado, memoria, nombre: botNombre(env, null), direccion: new URL(request.url).origin + BOT_RUTA });
  }
  if (request.method === 'POST' && p === '/teams/bot/probar') {
    if (!cfg.id || !cfg.secreto) return jsonError('Faltan cargar los secretos del bot (TEAMS_BOT_APP_ID y TEAMS_BOT_SECRET).', 409);
    try { await botToken(env, true); }
    catch (e) { return jsonError('No se pudo conectar con Microsoft: ' + (e.name === 'TimeoutError' ? 'no respondió a tiempo' : e.message) + '. Revisá el App ID, el secreto' + (cfg.tenant ? ' y el tenant.' : '; si el bot es de un solo tenant, cargá TEAMS_BOT_TENANT.'), 502); }
    await env.DB.prepare('INSERT INTO auditoria (usuario_id, accion, detalle) VALUES (?1, ?2, ?3)').bind(yo.id, 'TEAMS_BOT_PRUEBA', 'Conexión con Microsoft').run();
    return okJson({});
  }
  return null;
}

const TRABAJADOR = {
  // Cron Trigger: registra las alertas en el histórico
  async scheduled(controller, env, ctx) {
    try {
      // Feriados: si falta el año en curso (o el siguiente, desde octubre), se traen de la API
      try { const f = await feriadosAlDia(env); if (f.length) console.log('Feriados: ' + JSON.stringify(f)); } catch (e) { console.error('Feriados: ' + e.message); }
      // Con el reloj simulado (alerta_parametros.ahora) el tiempo no avanza solo:
      // las alertas se procesan desde el botón de la demo. El cron no hace nada.
      const reloj = await env.DB.prepare('SELECT ahora FROM alerta_parametros WHERE id = 1').first();
      if (reloj && reloj.ahora) {
        console.log('Reloj simulado en ' + reloj.ahora + ': el cron no procesa (modo demo).');
        return;
      }
      const desde = await ultimoAvisoId(env);
      const r = await procesarAlertas(env);
      if (desde != null) await enviarPush(env, desde, 'https://helios.invalid');
      console.log(`Alertas: ${r.registradas_o_actualizadas} registradas o actualizadas, ${r.resueltas} resueltas automáticamente (${r.filas_leidas} filas leídas, ${r.filas_escritas} escritas)`);
    } catch (err) {
      console.error(err.message);
      throw err;
    }
  },

  // Dashboard y API.
  // Para la demo la página es pública; en producción conviene protegerla
  // con Cloudflare Access.
  // Pedidos web: atiende el pedido y, si creó avisos, los manda como push a los dispositivos suscriptos
  async fetch(request, env, ctx) {
    const desde = request.method === 'POST' ? await ultimoAvisoId(env) : null;
    // Teams (parche 70): novedades de las salas de crisis al canal, solo con el secreto TEAMS_WEBHOOK
    const desdeTeams = await teamsMarca(env, request, new URL(request.url).pathname.replace(/\/+$/, ''));
    const respuesta = await TRABAJADOR.atender(request, env, ctx);
    if (desde != null) {
      const envio = enviarPush(env, desde, new URL(request.url).origin).catch((e) => console.error('Push: ' + e.message));
      if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(envio); else await envio;
    }
    if (desdeTeams != null && respuesta.status < 400) {
      const envio = enviarTeamsSala(env, desdeTeams, new URL(request.url).origin).catch((e) => console.error('Teams: ' + e.message));
      if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(envio); else await envio;
    }
    return respuesta;
  },

  async atender(request, env, ctx) {
    const url = new URL(request.url);
    const ruta = url.pathname.replace(/\/+$/, '') || '/';
    try {
      if (!env.DB) throw new Error('No se encontró la base D1: falta el binding "DB".');
      // Bot de Teams (parche 76): lo llama Microsoft con su propio token, sin sesión
      if (ruta === BOT_RUTA && request.method === 'POST') return await botTeamsRuta(env, request, ctx);
      // Login y permisos: devuelve una respuesta (login, 401, 403...) o el usuario de la sesión
      const acceso = await controlarAcceso(env, request, ruta);
      if (acceso instanceof Response) return acceso;
      const yo = acceso.usuario;
      // Campanita de avisos (/api/avisos...)
      const avisosR = await rutasAvisos(env, request, ruta, yo);
      if (avisosR) return avisosR;
      // Avisos push en el dispositivo (/api/push/...)
      const pushR = await rutasPush(env, request, ruta, yo);
      if (pushR) return pushR;
      // Asistente de IA (/api/asistente): solo lee y propone, según los permisos del perfil
      const asistenteR = await rutasAsistente(env, request, ruta, yo);
      if (asistenteR) return asistenteR;
      // Recalcular las últimas 24 h (parche 37): revisión completa, solo Administrador
      if (ruta === '/api/admin/recalcular' && request.method === 'POST') {
        if (!puede(yo, 'admin_umbrales')) return jsonError('Solo el Administrador puede recalcular.', 403);
        const r = await procesarAlertas(env, { completa: true });
        await auditar(env, yo.id, 'RECALCULAR_24H', r.registradas_o_actualizadas + ' registradas o actualizadas, ' + r.resueltas + ' cerradas');
        return okJson(r);
      }
      // Ticketera: detalle de una alerta, evidencia y catálogo de resolución (controla sus propios permisos)
      // Comunicados de incidente (parche 46): controla sus propios permisos
      // Sala de crisis (parche 69): controla sus propios permisos
      const salaR = await rutasSalaCrisis(env, request, ruta, yo);
      if (salaR) return salaR;
      const misTareasR = await rutasMisTareas(env, request, ruta, yo);   // «Mis tareas» del Analista (parche 81)
      if (misTareasR) return misTareasR;
      const comunicadosR = await rutasComunicados(env, request, ruta, yo);
      if (comunicadosR) return comunicadosR;
      const ticketeraR = await rutasTicketera(env, request, ruta, yo);
      if (ticketeraR) return ticketeraR;
      // Asignación de alertas y "Mis alertas": controla sus propios permisos
      const asignacion = await rutasAsignacion(env, request, ruta, yo);
      if (asignacion) return asignacion;
      // Administración (/admin y /api/admin/...): controla sus propios permisos
      const admin = await rutasAdmin(env, request, ruta, url, yo);
      if (admin) return admin;
      if (request.method === 'GET' && ruta === '/inicio') {
        const destino = url.searchParams.has('demo') && puede(yo, 'demo') ? (url.searchParams.get('demo') === 'oficial' ? '/?demo=oficial' : '/?demo') : inicioDe(yo);
        return Response.redirect(new URL(destino, request.url).toString(), 302);
      }
      if (request.method === 'GET' && ruta === '/') {
        // Soporte no ve el tablero general (salvo para cambiar la contraseña temporal, que se hace en esta página)
        if (!puede(yo, 'tablero') && !yo.debe_cambiar) return Response.redirect(new URL(inicioDe(yo), request.url).toString(), 302);
        return new Response(HTML, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' } });
      }
      if (request.method === 'POST' && ruta === '/api/prealertas/avisar') {
        if (!puede(yo, 'avisar_prealerta')) return jsonError('Tu perfil no puede avisar pre-alertas.', 403);
        return await avisarPrealerta(env, request, yo);
      }
      // Marcador liviano para la actualización automática del tablero (parche 42): 1 fila
      if (request.method === 'GET' && ruta === '/api/tablero/version') {
        if (!puede(yo, 'tablero')) return jsonError('Tu perfil no usa el tablero general.', 403);
        const v = await env.DB.prepare('SELECT tablero_revision AS revision FROM alerta_parametros WHERE id = 1').first();
        return Response.json({ ok: true, revision: v ? v.revision : null }, { headers: { 'cache-control': 'no-store' } });
      }
      if (request.method === 'GET' && ruta === '/api/tablero/periodo') {
        if (!puede(yo, 'tablero')) return jsonError('Tu perfil no usa el tablero general.', 403);
        return await resumenPeriodo(env, url);
      }
      if (request.method === 'GET' && ruta === '/api/dashboard') {
        if (!puede(yo, 'tablero')) return jsonError('Tu perfil trabaja desde "Mis alertas": el tablero general no está disponible.', 403);
        const d = await datosDashboard(env);
        if (puede(yo, 'mis_alertas')) d.mis_pendientes = await contarMisAlertas(env, yo);   // número del botón "Mis alertas"
        return Response.json(d, { headers: { 'cache-control': 'no-store' } });
      }
      // Ejecutar el proceso a mano (POST desde el botón; GET para abrirlo en el navegador)
      // Revisión manual: ya no hay botón (parche 34). La ruta solo existe para las pruebas de la PC (PERMITIR_REVISION_MANUAL = '1');
      // en Cloudflare las revisiones las hacen las escenas de la demo y el cron (o, más adelante, la llegada de datos).
      if (env.PERMITIR_REVISION_MANUAL === '1' && request.method === 'POST' && ruta === '/api/procesar') {
        // Completa, salvo ?incremental=1 (para probar la revisión incremental como la haría el cron)
        const r = await procesarAlertas(env, { completa: url.searchParams.get('incremental') !== '1' });
        await auditar(env, yo.id, 'PROCESAR', null);
        return Response.json(r);
      }
      const m = ruta.match(/^\/api\/alertas\/([0-9a-f]{32})\/(reconocer|resolver)$/);
      if (request.method === 'POST' && m) {
        if (!env.DB) throw new Error('No se encontró la base D1: falta el binding "DB".');
        return await accionAlerta(env, m[1], m[2], request, yo);
      }
      // Modo demo
      if (ruta.startsWith('/api/demo')) {
        if (!env.DB) throw new Error('No se encontró la base D1: falta el binding "DB".');
        if (request.method === 'GET' && ruta === '/api/demo') return Response.json(await demoEstado(env), { headers: { 'cache-control': 'no-store' } });
        if (request.method === 'POST' && ruta === '/api/demo/preparar') { const r = await demoPreparar(env); await auditar(env, yo.id, 'DEMO_PREPARAR', null); return Response.json(r); }
        if (request.method === 'POST' && ruta === '/api/demo/siguiente') return Response.json(await demoSiguiente(env));
        // Demo oficial (parche 82): endpoints separados de la demo de siempre
        if (request.method === 'GET' && ruta === '/api/demo-oficial') return Response.json(await demoOficialEstado(env), { headers: { 'cache-control': 'no-store' } });
        if (request.method === 'POST' && ruta === '/api/demo-oficial/preparar') { const r = await demoOficialPreparar(env); await auditar(env, yo.id, 'DEMO_OFICIAL_PREPARAR', null); return Response.json(r); }
        if (request.method === 'POST' && ruta === '/api/demo-oficial/siguiente') return Response.json(await demoOficialSiguiente(env, yo));
      }
      return Response.json({ ok: false, error: 'Ruta no encontrada: ' + ruta }, { status: 404 });
    } catch (err) {
      console.error(err.message);
      return Response.json({ ok: false, error: err.message }, { status: 500 });
    }
  },
};

export default TRABAJADOR;
